1	// Shader section (PLAN.md §3.7, comments spec 06): WebGL light bands behind
2	// static text.
3	// - Seamless 25 s loop: every time input is a periodic function of
4	//   phase = 2π · t / 25 s (noise drifts along a circle, bands move by one
5	//   wavelength), so t = 25 s renders exactly the t = 0 frame. t is kept modulo
6	//   25 s in JS so float precision never degrades.
7	// - Cheap: one full-screen triangle, 2-octave value noise, DPR capped at 1.5
8	//   and rendered at half that resolution, at most 60 fps, low-power context.
9	//   rAF only while the section is on screen and the tab is visible.
10	// - Fallbacks: no WebGL / lost context -> the section's CSS gradient stays
11	//   (the canvas never fades in). Reduced motion -> one static frame.
12	(function () {
13	  'use strict';
14	
15	  var LOOP_MS = 25000;
16	  var MAX_DPR = 1.5;
17	  // The picture is soft gradients only (text is HTML), so the canvas renders
18	  // at half resolution and CSS scales it up: no visible difference, about a
19	  // quarter of the pixel work. Overridable for testing via data-render-scale.
20	  var RENDER_SCALE = 0.5;
21	  var RESIZE_DEBOUNCE_MS = 100;
22	  var FRAME_MS = 1000 / 60; // slow motion: more than 60 fps only costs GPU and battery
23	
24	  var VERTEX = [
25	    'attribute vec2 a_pos;',
26	    'void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }',
27	  ].join('\n');
28	
29	  var FRAGMENT = [
30	    '#ifdef GL_FRAGMENT_PRECISION_HIGH',
31	    'precision highp float;',
32	    '#else',
33	    'precision mediump float;',
34	    '#endif',
35	    'uniform vec2 u_res;',
36	    'uniform float u_phase;',
37	    '',
38	    'float hash(vec2 p) {',
39	    '  vec3 p3 = fract(vec3(p.xyx) * 0.1031);',
40	    '  p3 += dot(p3, p3.yzx + 33.33);',
41	    '  return fract((p3.x + p3.y) * p3.z);',
42	    '}',
43	    '',
44	    'float noise(vec2 p) {',
45	    '  vec2 i = floor(p);',
46	    '  vec2 f = fract(p);',
47	    '  vec2 u = f * f * (3.0 - 2.0 * f);',
48	    '  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),',
49	    '             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
50	    '}',
51	    '',
52	    '// two octaves only',
53	    'float fbm(vec2 p) {',
54	    '  return 0.65 * noise(p) + 0.35 * noise(p * 2.07 + 7.3);',
55	    '}',
56	    '',
57	    '// colour ramp sampled from screen.png: near-black -> deep olive -> gold -> brand yellow',
58	    'vec3 ramp(float t) {',
59	    '  vec3 c0 = vec3(0.063, 0.063, 0.067);', // #101011
60	    '  vec3 c1 = vec3(0.165, 0.141, 0.094);', // #2a2418
61	    '  vec3 c2 = vec3(0.373, 0.306, 0.114);', // #5f4e1d
62	    '  vec3 c3 = vec3(0.561, 0.443, 0.129);', // #8f7121
63	    '  vec3 c4 = vec3(0.949, 0.749, 0.145);', // #f2bf25
64	    '  vec3 c = mix(c0, c1, smoothstep(0.0, 0.25, t));',
65	    '  c = mix(c, c2, smoothstep(0.25, 0.5, t));',
66	    '  c = mix(c, c3, smoothstep(0.5, 0.75, t));',
67	    '  return mix(c, c4, smoothstep(0.75, 1.0, t));',
68	    '}',
69	    '',
70	    'void main() {',
71	    '  vec2 uv = gl_FragCoord.xy / u_res;', // 0..1, y up
72	    '  vec2 p = gl_FragCoord.xy / u_res.y;', // height-normalised
73	    '  vec2 loop = vec2(cos(u_phase), sin(u_phase));',
74	    '',
75	    '  // slow, periodic domain warp',
76	    '  vec2 q = vec2(fbm(p * 1.1 + loop * 0.45),',
77	    '                fbm(p * 1.1 + vec2(5.2, 1.3) - loop.yx * 0.45));',
78	    '',
79	    '  // soft diagonal bands, upper-left to lower-right on screen',
80	    '  float s = dot(p + q * 0.25, vec2(0.64, 0.77));',
81	    '  float bands = smoothstep(0.08, 0.95, 0.5 + 0.5 * sin(s * 7.5 - u_phase));',
82	    '',
83	    '  // light rises from the bottom; the top stays near black',
84	    '  float rise = pow(clamp(0.94 - uv.y + 0.12 * (q.y - 0.5), 0.0, 1.0), 1.15);',
85	    '  float glow = rise * mix(0.4, 1.15, bands) * (0.6 + 0.55 * q.x);',
86	    '',
87	    '  vec3 col = ramp(clamp(glow, 0.0, 1.0));',
88	    '  col += (hash(gl_FragCoord.xy + u_phase) - 0.5) / 255.0;', // dither against banding
89	    '  gl_FragColor = vec4(col, 1.0);',
90	    '}',
91	  ].join('\n');
92	
93	  function compile(gl, type, source) {
94	    var shader = gl.createShader(type);
95	    gl.shaderSource(shader, source);
96	    gl.compileShader(shader);
97	    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
98	      gl.deleteShader(shader);
99	      return null;
100	    }
101	    return shader;
102	  }
103	
104	  function setup(gl) {
105	    var vs = compile(gl, gl.VERTEX_SHADER, VERTEX);
106	    var fs = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
107	    if (!vs || !fs) return null;
108	    var program = gl.createProgram();
109	    gl.attachShader(program, vs);
110	    gl.attachShader(program, fs);
111	    gl.linkProgram(program);
112	    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
113	    gl.useProgram(program);
114	
115	    // one triangle that covers the viewport
116	    var buffer = gl.createBuffer();
117	    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
118	    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
119	    var pos = gl.getAttribLocation(program, 'a_pos');
120	    gl.enableVertexAttribArray(pos);
121	    gl.vertexAttribPointer(pos, 2, gl.FLOAT, false, 0, 0);
122	
123	    return {
124	      res: gl.getUniformLocation(program, 'u_res'),
125	      phase: gl.getUniformLocation(program, 'u_phase'),
126	    };
127	  }
128	
129	  function init() {
130	    var root = document.querySelector('[data-shader]');
131	    var canvas = root && root.querySelector('[data-shader-canvas]');
132	    if (!canvas) return;
133	
134	    var gl = canvas.getContext('webgl', {
135	      alpha: false,
136	      antialias: false,
137	      depth: false,
138	      stencil: false,
139	      powerPreference: 'low-power',
140	    });
141	    if (!gl) return; // CSS gradient stays
142	
143	    var uniforms = setup(gl);
144	    if (!uniforms) return;
145	
146	    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
147	    var renderScale = parseFloat(root.getAttribute('data-render-scale')) || RENDER_SCALE;
148	    var elapsed = 0;
149	    var last = null;
150	    var frame = 0;
151	    var visible = false;
152	    var lost = false;
153	    var resizeTimer = 0;
154	    var lastDraw = -Infinity;
155	
156	    function draw() {
157	      if (lost) return;
158	      gl.uniform2f(uniforms.res, canvas.width, canvas.height);
159	      gl.uniform1f(uniforms.phase, (2 * Math.PI * elapsed) / LOOP_MS);
160	      gl.drawArrays(gl.TRIANGLES, 0, 3);
161	      root.classList.add('shader--ready');
162	    }
163	
164	    function resize() {
165	      var dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR) * renderScale;
166	      var w = Math.max(1, Math.round(canvas.clientWidth * dpr));
167	      var h = Math.max(1, Math.round(canvas.clientHeight * dpr));
168	      if (w !== canvas.width || h !== canvas.height) {
169	        canvas.width = w;
170	        canvas.height = h;
171	        gl.viewport(0, 0, w, h);
172	      }
173	      draw();
174	    }
175	
176	    function running() {
177	      return visible && !document.hidden && !reduce.matches && !lost;
178	    }
179	
180	    function tick(now) {
181	      frame = 0;
182	      // clamp long gaps so the motion never jumps after a stall
183	      if (last !== null) elapsed = (elapsed + Math.min(now - last, 100)) % LOOP_MS;
184	      last = now;
185	      // 60 fps cap: time always advances, only the drawing is skipped. The
186	      // draw schedule moves in exact 1/60 s steps, so a 144 Hz screen averages
187	      // 60; the 1 ms tolerance keeps a 60 Hz screen from dropping to 30.
188	      var since = now - lastDraw;
189	      if (since >= FRAME_MS - 1) {
190	        lastDraw = since > 2 * FRAME_MS ? now : lastDraw + FRAME_MS;
191	        draw();
192	      }
193	      update();
194	    }
195	
196	    function update() {
197	      if (running()) {
198	        if (!frame) frame = requestAnimationFrame(tick);
199	      } else {
200	        if (frame) cancelAnimationFrame(frame);
201	        frame = 0;
202	        last = null;
203	      }
204	    }
205	
206	    if ('IntersectionObserver' in window) {
207	      new IntersectionObserver(function (entries) {
208	        visible = entries[entries.length - 1].isIntersecting;
209	        update();
210	      }).observe(root);
211	    } else {
212	      visible = true;
213	    }
214	
