1	// Hero slider (PLAN.md §3.4, comments spec 04).
2	// - Autoplay every --slide-interval (3 s); the crossfade and zoom are CSS
3	//   transitions on the class change (css/hero.css).
4	// - The progress bar is driven from the same clock, so bar and slide change
5	//   never drift apart. Timing uses requestAnimationFrame + performance.now,
6	//   which Playwright's page.clock controls.
7	// - Pauses while a control is hovered, while keyboard focus is inside the
8	//   hero, while the tab is hidden and while the hero is off-screen.
9	// - Pause/play toggle next to the progress bar (WCAG 2.2.2).
10	// - Reduced motion: no autoplay (manual changes still crossfade).
11	(function () {
12	  'use strict';
13	
14	  var SWIPE_MIN = 50; // px
15	
16	  function parseTime(value) {
17	    var text = String(value).trim();
18	    var n = parseFloat(text);
19	    if (isNaN(n)) return 0;
20	    return /ms$/.test(text) ? n : n * 1000;
21	  }
22	
23	  function init() {
24	    var root = document.querySelector('[data-slider]');
25	    if (!root) return;
26	
27	    var slides = root.querySelectorAll('[data-slide]');
28	    var dots = root.querySelectorAll('[data-slider-dot]');
29	    var controls = root.querySelectorAll(
30	      '[data-slider-prev], [data-slider-next], [data-slider-progress]',
31	    );
32	    if (slides.length < 2) return;
33	
34	    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
35	    var interval = parseTime(getComputedStyle(root).getPropertyValue('--slide-interval')) || 3000;
36	
37	    var index = 0;
38	    var elapsed = 0;
39	    var last = null;
40	    var frame = 0;
41	    var pauseButton = root.querySelector('[data-slider-pause]');
42	    var paused = { hover: false, focus: false, hidden: document.hidden, offscreen: false };
43	    // Explicit choice from the pause/play toggle: null (not used), 'paused' or
44	    // 'playing'. Once used it wins over the automatic hover/focus pauses, so
45	    // pressing "play" with the keyboard (focus still inside) really plays.
46	    var userChoice = null;
47	
48	    function autoplay() {
49	      if (reduce.matches || paused.hidden || paused.offscreen) return false;
50	      if (userChoice) return userChoice === 'playing';
51	      return !paused.hover && !paused.focus;
52	    }
53	
54	    function renderProgress() {
55	      Array.prototype.forEach.call(dots, function (dot, i) {
56	        var fill = dot.firstElementChild;
57	        if (!fill) return;
58	        // Inline transform only while autoplay is possible; otherwise the CSS
59	        // default applies (active bar full, others empty).
60	        fill.style.transform =
61	          i === index && !reduce.matches ? 'scaleX(' + Math.min(elapsed / interval, 1) + ')' : '';
62	      });
63	    }
64	
65	    function show(next) {
66	      index = (next + slides.length) % slides.length;
67	      elapsed = 0;
68	      Array.prototype.forEach.call(slides, function (slide, i) {
69	        var active = i === index;
70	        slide.classList.toggle('hero__slide--active', active);
71	        if (active) slide.removeAttribute('aria-hidden');
72	        else slide.setAttribute('aria-hidden', 'true');
73	      });
74	      Array.prototype.forEach.call(dots, function (dot, i) {
75	        var active = i === index;
76	        dot.classList.toggle('hero__dot--active', active);
77	        if (active) dot.setAttribute('aria-current', 'true');
78	        else dot.removeAttribute('aria-current');
79	      });
80	      renderProgress();
81	    }
82	
83	    function tick(now) {
84	      frame = 0;
85	      // Clamp long gaps (throttled frames) so the bar never skips ahead.
86	      if (last !== null) elapsed += Math.min(now - last, 100);
87	      last = now;
88	      if (elapsed >= interval) show(index + 1);
89	      else renderProgress();
90	      update();
91	    }
92	
93	    function update() {
94	      if (autoplay()) {
95	        if (!frame) frame = requestAnimationFrame(tick);
96	      } else {
97	        if (frame) cancelAnimationFrame(frame);
98	        frame = 0;
99	        last = null;
100	        renderProgress();
101	      }
102	    }
103	
104	    function go(step) {
105	      show(index + step);
106	      update();
107	    }
108	
109	    root.querySelector('[data-slider-prev]').addEventListener('click', function () {
110	      go(-1);
111	    });
112	    root.querySelector('[data-slider-next]').addEventListener('click', function () {
113	      go(1);
114	    });
115	    Array.prototype.forEach.call(dots, function (dot, i) {
116	      dot.addEventListener('click', function () {
117	        if (i !== index) go(i - index);
118	      });
119	    });
120	
121	    // Keyboard: arrow keys while focus is inside the hero.
122	    root.addEventListener('keydown', function (event) {
123	      if (event.key === 'ArrowLeft') go(-1);
124	      else if (event.key === 'ArrowRight') go(1);
125	    });
126	
127	    // Pause on hover over the controls (mouse only; touch has no hover).
128	    Array.prototype.forEach.call(controls, function (el) {
129	      el.addEventListener('pointerenter', function (event) {
130	        if (event.pointerType !== 'mouse') return;
131	        paused.hover = true;
132	        update();
133	      });
134	      el.addEventListener('pointerleave', function (event) {
135	        if (event.pointerType !== 'mouse') return;
136	        paused.hover = false;
137	        update();
138	      });
139	    });
140	
141	    // Pause while keyboard focus is inside (mouse clicks don't match :focus-visible).
142	    root.addEventListener('focusin', function (event) {
143	      paused.focus = event.target.matches(':focus-visible');
144	      update();
145	    });
146	    root.addEventListener('focusout', function (event) {
147	      if (!root.contains(event.relatedTarget)) {
148	        paused.focus = false;
149	        update();
150	      }
151	    });
152	
153	    document.addEventListener('visibilitychange', function () {
154	      paused.hidden = document.hidden;
155	      update();
156	    });
157	
158	    if ('IntersectionObserver' in window) {
159	      new IntersectionObserver(function (entries) {
160	        paused.offscreen = !entries[entries.length - 1].isIntersecting;
161	        update();
162	      }).observe(root);
163	    }
164	
165	    // Pause/play toggle (WCAG 2.2.2). Hidden under reduced motion, where
166	    // there is no autoplay to pause.
167	    function syncPauseButton() {
168	      if (!pauseButton) return;
169	      pauseButton.hidden = reduce.matches;
170	      pauseButton.setAttribute('aria-pressed', String(userChoice === 'paused'));
171	    }
172	
173	    if (pauseButton) {
174	      pauseButton.addEventListener('click', function () {
175	        userChoice = userChoice === 'paused' ? 'playing' : 'paused';
176	        syncPauseButton();
177	        update();
178	      });
179	    }
180	
181	    reduce.addEventListener('change', function () {
182	      syncPauseButton();
183	      update();
184	    });
185	    syncPauseButton();
186	
187	    // Touch swipe (the arrows are hidden below 1024 px).
188	    var start = null;
189	    root.addEventListener('pointerdown', function (event) {
190	      start = event.pointerType === 'touch' ? { x: event.clientX, y: event.clientY } : null;
191	    });
192	    root.addEventListener('pointerup', function (event) {
193	      if (!start) return;
194	      var dx = event.clientX - start.x;
195	      var dy = event.clientY - start.y;
196	      start = null;
197	      if (Math.abs(dx) >= SWIPE_MIN && Math.abs(dx) > Math.abs(dy)) go(dx < 0 ? 1 : -1);
198	    });
199	    root.addEventListener('pointercancel', function () {
200	      start = null;
201	    });
202	
203	    show(0);
204	    update();
205	  }
206	
207	  if (document.readyState === 'loading') {
208	    document.addEventListener('DOMContentLoaded', init);
209	  } else {
210	    init();
211	  }
212	})();
