1	// Hero lamps (PLAN.md §3.3, comments spec 03): click / Enter / Space toggles a
2	// lamp's light. The visuals are CSS (css/lamps.css); this script only keeps
3	// the state:
4	// - aria-pressed on the button, .light--on on its light group;
5	// - .hero--lit (any lamp on) and .hero--lit-1/2/3 on the hero for the light
6	//   layer, the room dim and the headline easter egg (at 3);
7	// - the first-visit hint: shown until the first click, remembered in
8	//   localStorage (try/catch: blocked storage just means it shows again).
9	(function () {
10	  'use strict';
11	
12	  var HINT_KEY = 'sollux:lamp-hint-seen';
13	
14	  function hintSeen() {
15	    try {
16	      return window.localStorage.getItem(HINT_KEY) === '1';
17	    } catch (e) {
18	      return false;
19	    }
20	  }
21	
22	  function rememberHint() {
23	    try {
24	      window.localStorage.setItem(HINT_KEY, '1');
25	    } catch (e) {
26	      // storage blocked: nothing to remember
27	    }
28	  }
29	
30	  function init() {
31	    var hero = document.querySelector('[data-slider]');
32	    if (!hero) return;
33	    var lamps = hero.querySelectorAll('[data-lamp]');
34	    var lights = hero.querySelectorAll('[data-light]');
35	    var hint = hero.querySelector('[data-lamp-hint]');
36	
37	    if (hint && !hintSeen()) hint.hidden = false;
38	
39	    function updateRoom() {
40	      var count = 0;
41	      Array.prototype.forEach.call(lamps, function (lamp) {
42	        if (lamp.getAttribute('aria-pressed') === 'true') count++;
43	      });
44	      hero.classList.toggle('hero--lit', count > 0);
45	      for (var n = 1; n <= 3; n++) hero.classList.toggle('hero--lit-' + n, count === n);
46	    }
47	
48	    Array.prototype.forEach.call(lamps, function (lamp, i) {
49	      lamp.addEventListener('click', function () {
50	        var on = lamp.getAttribute('aria-pressed') !== 'true';
51	        lamp.setAttribute('aria-pressed', String(on));
52	        if (lights[i]) lights[i].classList.toggle('light--on', on);
53	        updateRoom();
54	        if (hint && !hint.hidden) {
55	          hint.hidden = true;
56	          rememberHint();
57	        }
58	      });
59	    });
60	  }
61	
62	  if (document.readyState === 'loading') {
63	    document.addEventListener('DOMContentLoaded', init);
64	  } else {
65	    init();
66	  }
67	})();
