1	// Hero lamp parallax (PLAN.md §3.3, the brief's second idea): the lamps drift
2	// slightly with the cursor, the nearest one most (data-depth on each lamp).
3	// - Offset: the cursor's position in the hero, from -1 to 1 on each axis,
4	//   clamped to the unit circle, times --lamp-parallax (12 px at a 1920 px
5	//   stage, scaled with the stage) times the lamp's depth.
6	// - Smoothed in a requestAnimationFrame loop (exponential follow), which
7	//   runs only while something is still moving.
8	// - The values go to CSS custom properties; css/lamps.css applies them with
9	//   `translate` (transform only). The light group moves with its lamp, and
10	//   the pool on the rock moves only --lamp-parallax-pool of that.
11	// - Mouse only (hover + fine pointer), off under reduced motion. When the
12	//   cursor leaves the hero the lamps ease back to rest; at rest the inline
13	//   properties are removed, so the hero is exactly as designed.
14	// - While moving, .hero--parallax promotes the moving parts to their own
15	//   layers (will-change), so the blurred light shapes aren't repainted every
16	//   frame; at rest the class goes, and so do the extra layers.
17	(function () {
18	  'use strict';
19	
20	  var SMOOTH_MS = 160; // time constant of the follow
21	  var STAGE_REF = 1920; // --lamp-parallax is given for this stage width
22	  var EPSILON = 0.002;
23	
24	  function init() {
25	    var hero = document.querySelector('[data-slider]');
26	    if (!hero) return;
27	    var lamps = hero.querySelectorAll('[data-lamp]');
28	    var lights = hero.querySelectorAll('[data-light]');
29	    if (!lamps.length) return;
30	    var stage = lamps[0].parentElement;
31	
32	    var fine = window.matchMedia('(hover: hover) and (pointer: fine)');
33	    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
34	    var style = getComputedStyle(hero);
35	    var maxPx = parseFloat(style.getPropertyValue('--lamp-parallax')) || 12;
36	    var poolFollow = parseFloat(style.getPropertyValue('--lamp-parallax-pool'));
37	    if (isNaN(poolFollow)) poolFollow = 0.3;
38	    var depth = Array.prototype.map.call(lamps, function (lamp) {
39	      var d = parseFloat(lamp.getAttribute('data-depth'));
40	      return isNaN(d) ? 1 : d;
41	    });
42	
43	    var pointer = null; // last mouse position (client px), null when outside the page
44	    var cur = { x: 0, y: 0 };
45	    var frame = 0;
46	    var last = null;
47	    var atRest = true;
48	
49	    function target() {
50	      if (!pointer || !fine.matches || reduce.matches) return { x: 0, y: 0 };
51	      var r = hero.getBoundingClientRect();
52	      if (pointer.x < r.left || pointer.x > r.right || pointer.y < r.top || pointer.y > r.bottom) {
53	        return { x: 0, y: 0 };
54	      }
55	      var x = ((pointer.x - r.left) / r.width) * 2 - 1;
56	      var y = ((pointer.y - r.top) / r.height) * 2 - 1;
57	      var len = Math.sqrt(x * x + y * y);
58	      return len > 1 ? { x: x / len, y: y / len } : { x: x, y: y };
59	    }
60	
61	    function render(scale) {
62	      if (cur.x === 0 && cur.y === 0) {
63	        if (atRest) return;
64	        atRest = true;
65	        hero.classList.remove('hero--parallax');
66	        Array.prototype.forEach.call(lamps, function (lamp) {
67	          lamp.style.removeProperty('--parallax');
68	        });
69	        Array.prototype.forEach.call(lights, function (light) {
70	          light.style.removeProperty('--parallax');
71	          light.style.removeProperty('--parallax-pool');
72	        });
73	        return;
74	      }
75	      if (atRest) hero.classList.add('hero--parallax');
76	      atRest = false;
77	      Array.prototype.forEach.call(lamps, function (lamp, i) {
78	        var dx = cur.x * scale * depth[i];
79	        var dy = cur.y * scale * depth[i];
80	        var move = dx.toFixed(2) + 'px ' + dy.toFixed(2) + 'px';
81	        lamp.style.setProperty('--parallax', move);
82	        if (lights[i]) {
83	          lights[i].style.setProperty('--parallax', move);
84	          lights[i].style.setProperty(
85	            '--parallax-pool',
86	            (dx * (poolFollow - 1)).toFixed(2) + 'px ' + (dy * (poolFollow - 1)).toFixed(2) + 'px',
87	          );
88	        }
89	      });
90	    }
91	
92	    function tick(now) {
93	      frame = 0;
94	      // reads first (target, stage size), then writes (render)
95	      var t = target();
96	      var scale = (stage.getBoundingClientRect().width / STAGE_REF) * maxPx;
97	      var dt = last === null ? 16 : Math.min(now - last, 64);
98	      last = now;
99	      var k = 1 - Math.exp(-dt / SMOOTH_MS);
100	      cur.x += (t.x - cur.x) * k;
101	      cur.y += (t.y - cur.y) * k;
102	      var settled = Math.abs(t.x - cur.x) < EPSILON && Math.abs(t.y - cur.y) < EPSILON;
103	      if (settled) cur = t;
104	      render(scale);
105	      if (settled) last = null;
106	      else frame = requestAnimationFrame(tick);
107	    }
108	
109	    function wake() {
110	      if (!frame) frame = requestAnimationFrame(tick);
111	    }
112	
113	    document.addEventListener(
114	      'pointermove',
115	      function (event) {
116	        if (event.pointerType !== 'mouse') return;
117	        pointer = { x: event.clientX, y: event.clientY };
118	        wake();
119	      },
120	      { passive: true },
121	    );
122	    // cursor left the window
123	    document.addEventListener('pointerout', function (event) {
124	      if (event.pointerType === 'mouse' && !event.relatedTarget) {
125	        pointer = null;
126	        wake();
127	      }
128	    });
129	    // the hero moves under a still cursor while scrolling
130	    window.addEventListener('scroll', wake, { passive: true });
131	    fine.addEventListener('change', wake);
132	    reduce.addEventListener('change', wake);
133	  }
134	
135	  if (document.readyState === 'loading') {
136	    document.addEventListener('DOMContentLoaded', init);
137	  } else {
138	    init();
139	  }
140	})();
141

1	// Shader section (PLAN.md §3.7, comments spec 06): WebGL light bands behind
2	// static text.
3	// - Seamless 25 s loop: every time input is a periodic function of
4	//   phase = 2π · t / 25 s (noise drifts along a circle, bands move by one
5	//   wavelength), so t = 25 s renders exactly the t = 0 frame. t is kept modulo
6	//   25 s in JS so float precision never degrades.
7	// - Cheap: one full-screen triangle, 2-octave value noise, DPR capped at 1.5
8	//   and rendered at half that resolution, at most 60 fps, low-power context.
9	//   rAF only while the section is on screen and the tab is visible.
10	// - Fallbacks: no WebGL / lost context -> the section's CSS gradient stays
11	//   (the canvas never fades in). Reduced motion -> one static frame.
12	(function () {
13	  'use strict';
14	
15	  var LOOP_MS = 25000;
16	  var MAX_DPR = 1.5;
17	  // The picture is soft gradients only (text is HTML), so the canvas renders
18	  // at half resolution and CSS scales it up: no visible difference, about a
19	  // quarter of the pixel work. Overridable for testing via data-render-scale.
20	  var RENDER_SCALE = 0.5;
21	  var RESIZE_DEBOUNCE_MS = 100;
22	  var FRAME_MS = 1000 / 60; // slow motion: more than 60 fps only costs GPU and battery
23	
24	  var VERTEX = [
25	    'attribute vec2 a_pos;',
26	    'void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }',
27	  ].join('\n');
28	
29	  var FRAGMENT = [
30	    '#ifdef GL_FRAGMENT_PRECISION_HIGH',
31	    'precision highp float;',
32	    '#else',
33	    'precision mediump float;',
34	    '#endif',
35	    'uniform vec2 u_res;',
36	    'uniform float u_phase;',
37	    '',
38	    'float hash(vec2 p) {',
39	    '  vec3 p3 = fract(vec3(p.xyx) * 0.1031);',
40	    '  p3 += dot(p3, p3.yzx + 33.33);',
41	    '  return fract((p3.x + p3.y) * p3.z);',
42	    '}',
43	    '',
44	    'float noise(vec2 p) {',
45	    '  vec2 i = floor(p);',
46	    '  vec2 f = fract(p);',
47	    '  vec2 u = f * f * (3.0 - 2.0 * f);',
48	    '  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),',
49	    '             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);',
50	    '}',
51	    '',
52	    '// two octaves only',
53	    'float fbm(vec2 p) {',
54	    '  return 0.65 * noise(p) + 0.35 * noise(p * 2.07 + 7.3);',
55	    '}',
56	    '',
57	    '// colour ramp sampled from screen.png: near-black -> deep olive -> gold -> brand yellow',
58	    'vec3 ramp(float t) {',
59	    '  vec3 c0 = vec3(0.063, 0.063, 0.067);', // #101011
60	    '  vec3 c1 = vec3(0.165, 0.141, 0.094);', // #2a2418
61	    '  vec3 c2 = vec3(0.373, 0.306, 0.114);', // #5f4e1d
62	    '  vec3 c3 = vec3(0.561, 0.443, 0.129);', // #8f7121
63	    '  vec3 c4 = vec3(0.949, 0.749, 0.145);', // #f2bf25
64	    '  vec3 c = mix(c0, c1, smoothstep(0.0, 0.25, t));',
65	    '  c = mix(c, c2, smoothstep(0.25, 0.5, t));',
66	    '  c = mix(c, c3, smoothstep(0.5, 0.75, t));',
67	    '  return mix(c, c4, smoothstep(0.75, 1.0, t));',
68	    '}',
69	    '',
70	    'void main() {',
71	    '  vec2 uv = gl_FragCoord.xy / u_res;', // 0..1, y up
72	    '  vec2 p = gl_FragCoord.xy / u_res.y;', // height-normalised
73	    '  vec2 loop = vec2(cos(u_phase), sin(u_phase));',
74	    '',
75	    '  // slow, periodic domain warp',
76	    '  vec2 q = vec2(fbm(p * 1.1 + loop * 0.45),',
77	    '                fbm(p * 1.1 + vec2(5.2, 1.3) - loop.yx * 0.45));',
78	    '',
79	    '  // soft diagonal bands, upper-left to lower-right on screen',
80	    '  float s = dot(p + q * 0.25, vec2(0.64, 0.77));',
81	    '  float bands = smoothstep(0.08, 0.95, 0.5 + 0.5 * sin(s * 7.5 - u_phase));',
82	    '',
83	    '  // light rises from the bottom; the top stays near black',
84	    '  float rise = pow(clamp(0.94 - uv.y + 0.12 * (q.y - 0.5), 0.0, 1.0), 1.15);',
85	    '  float glow = rise * mix(0.4, 1.15, bands) * (0.6 + 0.55 * q.x);',
86	    '',
87	    '  vec3 col = ramp(clamp(glow, 0.0, 1.0));',
88	    '  col += (hash(gl_FragCoord.xy + u_phase) - 0.5) / 255.0;', // dither against banding
89	    '  gl_FragColor = vec4(col, 1.0);',
90	    '}',
91	  ].join('\n');
92	
93	  function compile(gl, type, source) {
94	    var shader = gl.createShader(type);
95	    gl.shaderSource(shader, source);
96	    gl.compileShader(shader);
97	    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
98	      gl.deleteShader(shader);
99	      return null;
100	    }
101	    return shader;
102	  }
103	
104	  function setup(gl) {
105	    var vs = compile(gl, gl.VERTEX_SHADER, VERTEX);
106	    var fs = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
107	    if (!vs || !fs) return null;
108	    var program = gl.createProgram();
109	    gl.attachShader(program, vs);
110	    gl.attachShader(program, fs);
111	    gl.linkProgram(program);
112	    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
113	    gl.useProgram(program);
114	
115	    // one triangle that covers the viewport
116	    var buffer = gl.createBuffer();
117	    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
118	    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
119	    var pos = gl.getAttribLocation(program, 'a_pos');
120	    gl.enableVertexAttribArray(pos);
121	    gl.vertexAttribPointer(pos, 2, gl.FLOAT, false, 0, 0);
122	
123	    return {
124	      res: gl.getUniformLocation(program, 'u_res'),
125	      phase: gl.getUniformLocation(program, 'u_phase'),
126	    };
127	  }
128	
129	  function init() {
130	    var root = document.querySelector('[data-shader]');
131	    var canvas = root && root.querySelector('[data-shader-canvas]');
132	    if (!canvas) return;
133	
134	    var gl = canvas.getContext('webgl', {
135	      alpha: false,
136	      antialias: false,
137	      depth: false,
138	      stencil: false,
139	      powerPreference: 'low-power',
140	    });
141	    if (!gl) return; // CSS gradient stays
142	
143	    var uniforms = setup(gl);
144	    if (!uniforms) return;
145	
146	    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
147	    var renderScale = parseFloat(root.getAttribute('data-render-scale')) || RENDER_SCALE;
148	    var elapsed = 0;
149	    var last = null;
150	    var frame = 0;
151	    var visible = false;
152	    var lost = false;
153	    var resizeTimer = 0;
154	    var lastDraw = -Infinity;
155	
156	    function draw() {
157	      if (lost) return;
158	      gl.uniform2f(uniforms.res, canvas.width, canvas.height);
159	      gl.uniform1f(uniforms.phase, (2 * Math.PI * elapsed) / LOOP_MS);
160	      gl.drawArrays(gl.TRIANGLES, 0, 3);
161	      root.classList.add('shader--ready');
162	    }
163	
164	    function resize() {
165	      var dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR) * renderScale;
166	      var w = Math.max(1, Math.round(canvas.clientWidth * dpr));
167	      var h = Math.max(1, Math.round(canvas.clientHeight * dpr));
168	      if (w !== canvas.width || h !== canvas.height) {
169	        canvas.width = w;
170	        canvas.height = h;
171	        gl.viewport(0, 0, w, h);
172	      }
173	      draw();
174	    }
175	
176	    function running() {
177	      return visible && !document.hidden && !reduce.matches && !lost;
178	    }
179	
180	    function tick(now) {
181	      frame = 0;
182	      // clamp long gaps so the motion never jumps after a stall
183	      if (last !== null) elapsed = (elapsed + Math.min(now - last, 100)) % LOOP_MS;
184	      last = now;
185	      // 60 fps cap: time always advances, only the drawing is skipped. The
186	      // draw schedule moves in exact 1/60 s steps, so a 144 Hz screen averages
187	      // 60; the 1 ms tolerance keeps a 60 Hz screen from dropping to 30.
188	      var since = now - lastDraw;
189	      if (since >= FRAME_MS - 1) {
190	        lastDraw = since > 2 * FRAME_MS ? now : lastDraw + FRAME_MS;
191	        draw();
192	      }
193	      update();
194	    }
195	
196	    function update() {
197	      if (running()) {
198	        if (!frame) frame = requestAnimationFrame(tick);
199	      } else {
200	        if (frame) cancelAnimationFrame(frame);
201	        frame = 0;
202	        last = null;
203	      }
204	    }
205	
206	    if ('IntersectionObserver' in window) {
207	      new IntersectionObserver(function (entries) {
208	        visible = entries[entries.length - 1].isIntersecting;
209	        update();
210	      }).observe(root);
211	    } else {
212	      visible = true;
213	    }
214	
215	    if ('ResizeObserver' in window) {
216	      new ResizeObserver(function () {
217	        clearTimeout(resizeTimer);
218	        resizeTimer = setTimeout(resize, RESIZE_DEBOUNCE_MS);
219	      }).observe(canvas);
220	    }
221	
222	    document.addEventListener('visibilitychange', update);
223	    reduce.addEventListener('change', update);
224	
225	    canvas.addEventListener('webglcontextlost', function (event) {
226	      event.preventDefault();
227	      lost = true;
228	      root.classList.remove('shader--ready'); // back to the CSS gradient
229	      update();
230	    });
231	    canvas.addEventListener('webglcontextrestored', function () {
232	      uniforms = setup(gl);
233	      if (!uniforms) return;
234	      lost = false;
235	      resize();
236	      update();
237	    });
238	
239	    resize();
240	    update();
241	  }
242	
243	  if (document.readyState === 'loading') {
244	    document.addEventListener('DOMContentLoaded', init);
245	  } else {
246	    init();
247	  }
248	})();
249

1	/* Design tokens. Values from Figma call #3 (PLAN.md §0.3) and the comments spec.
2	   VP's / footer values are added after calls #4 and #5. */
3	:root {
4	  /* Colour */
5	  --c-white: #fff;
6	  --c-yellow: #f2bf25;
7	  --c-ink: #1e1e1e;
8	  --c-black: #101011;
9	  --c-line: #e7e7e7;
10	  --c-grey-hover: #4a4a4a; /* tile button hover (comments spec) */
11	  --c-control-bg: rgb(16 16 17 / 20%); /* hero arrows */
12	  --c-badge-bg: rgb(16 16 17 / 40%); /* Trustmate badge */
13	  --c-track: rgb(231 231 231 / 50%); /* progress bar track */
14	
15	  /* Tile backgrounds (Figma #4, 1:640 / 1:670 / 1:680; same as the images' own backgrounds) */
16	  --c-tile-blue: #72a3f3;
17	  --c-tile-cream: #fdf8eb;
18	  --c-tile-stone: #e8e4df;
19	
20	  /* Lamp light (css/lamps.css). The dim is how dark the room gets with 1, 2
21	     and 3 lamps on; tune by eye. No lamps on = 0, the hero as designed. */
22	  --lamp-dim-1: 0.06;
23	  --lamp-dim-2: 0.11;
24	  --lamp-dim-3: 0.15;
25	  --c-light-core: rgb(255 246 226);
26	  --c-light-warm: rgb(255 214 150);
27	  --c-light-amber: rgb(255 180 100);
28	  --c-light-ember: rgb(255 150 70);
29	  --c-light-text: #ffd27a;
30	
31	  /* Lamp parallax (js/lamp-parallax.js): largest offset of the nearest lamp
32	     at a 1920 px stage (scales with the stage), and how much of its lamp's
33	     offset the light pool on the rock follows. */
34	  --lamp-parallax: 12px;
35	  --lamp-parallax-pool: 0.3;
36	
37	  /* Shader section (measured from design/frames/screen.png; 1:707 is image-only).
38	     The WebGL colour ramp in js/shader.js uses the same values. */
39	  --c-shader-text: #f0f0f3;
40	  --c-shader-deep: #2a2418;
41	  --c-shader-olive: #5f4e1d;
42	  --c-shader-mid: #8f7121;
43	  --c-shader-gold: #b08a23;
44	
45	  /* Type */
46	  --ff: 'Red Hat Display', system-ui, -apple-system, 'Segoe UI', sans-serif;
47	  --fw-medium: 500;
48	  --fw-bold: 700;
49	  --fs-12: 0.75rem;
50	  --fs-13: 0.8125rem;
51	  --fs-14: 0.875rem;
52	  --fs-16: 1rem;
53	  --fs-21: 1.3125rem;
54	  --fs-hero: clamp(2.25rem, 1.6rem + 2.2vw, 3.5rem); /* 36 -> 56 px */
55	  /* 18 -> 21 px: benefit titles, tile eyebrows */
56	  --fs-lead: clamp(1.125rem, 1rem + 0.5vw, 1.3125rem);
57	  --fs-tile-title: clamp(1.5rem, 1.1rem + 1.25vw, 2rem); /* 24 -> 32 px */
58	  --fs-17: 1.0625rem;
59	  --fs-18: 1.125rem;
60	  --fs-shader: clamp(2rem, 1.4rem + 1.9vw, 3.25rem); /* 32 -> 52 px */
61	
62	  /* Motion (CLAUDE.md "Motion") */
63	  --ease: cubic-bezier(0.4, 0, 0.2, 1);
64	  --ease-out: cubic-bezier(0, 0, 0.2, 1);
65	  --dur-hover: 250ms;
66	  --dur-button: 200ms;
67	  --dur-tile: 500ms;
68	  --dur-fade: 600ms;
69	  --dur-zoom: 800ms;
70	  --dur-move: 500ms; /* menu panel, other movement */
71	  --slide-interval: 3000ms;
72	  --dur-flicker: 450ms; /* lamp switch-on flicker (opacity steps) */
73	  --dur-light-off: 300ms;
74	
75	  /* Transform amounts. Set to "no effect" under reduced motion below,
76	     so components never need their own reduced-motion branches for these. */
77	  --scale-tile-hover: 1.1;
78	  --scale-slide-in: 1.05;
79	  --move-menu: 100%;
80	
81	  /* Layout */
82	  --container: 1600px;
83	  --gutter: 16px; /* Figma: px-16 + max-w-1600 on navbar and hero container */
84	  --radius-pill: 100px;
85	  --header-h: 80px; /* mobile: 16 + 48 + 16 */
86	
87	  /* Lamp group in the hero stage (from design/lamp-positions.json):
88	     left edge 21.7708 %, right edge 80.5209 %, so 58.75 % wide, centred at 51.146 %. */
89	  --lamps-span: 0.5875;
90	  --lamps-center: 0.5115;
91	}
92	
93	@media (prefers-reduced-motion: reduce) {
94	  :root {
95	    /* No transforms (scale, movement). Opacity fades keep their durations. */
96	    --scale-tile-hover: 1;
97	    --scale-slide-in: 1;
98	    --move-menu: 0%;
99	    --dur-zoom: 0ms;
100	    --dur-move: 0ms;
101	  }
102	}
103

