/* Design tokens. Values from Figma call #3 (PLAN.md §0.3) and the comments spec.
   VP's / footer values are added after calls #4 and #5. */
:root {
  /* Colour */
  --c-white: #fff;
  --c-yellow: #f2bf25;
  --c-ink: #1e1e1e;
  --c-black: #101011;
  --c-line: #e7e7e7;
  --c-grey-hover: #4a4a4a; /* tile button hover (comments spec) */
  --c-control-bg: rgb(16 16 17 / 20%); /* hero arrows */
  --c-badge-bg: rgb(16 16 17 / 40%); /* Trustmate badge */
  --c-track: rgb(231 231 231 / 50%); /* progress bar track */

  /* Tile backgrounds (Figma #4, 1:640 / 1:670 / 1:680; same as the images' own backgrounds) */
  --c-tile-blue: #72a3f3;
  --c-tile-cream: #fdf8eb;
  --c-tile-stone: #e8e4df;

  /* Lamp light (css/lamps.css). The dim is how dark the room gets with 1, 2
     and 3 lamps on; tune by eye. No lamps on = 0, the hero as designed. */
  --lamp-dim-1: 0.06;
  --lamp-dim-2: 0.11;
  --lamp-dim-3: 0.15;
  --c-light-core: rgb(255 246 226);
  --c-light-warm: rgb(255 214 150);
  --c-light-amber: rgb(255 180 100);
  --c-light-ember: rgb(255 150 70);
  --c-light-text: #ffd27a;

  /* Lamp parallax (js/lamp-parallax.js): largest offset of the nearest lamp
     at a 1920 px stage (scales with the stage), and how much of its lamp's
     offset the light pool on the rock follows. */
  --lamp-parallax: 12px;
  --lamp-parallax-pool: 0.3;

  /* Shader section (measured from design/frames/screen.png; 1:707 is image-only).
     The WebGL colour ramp in js/shader.js uses the same values. */
  --c-shader-text: #f0f0f3;
  --c-shader-deep: #2a2418;
  --c-shader-olive: #5f4e1d;
  --c-shader-mid: #8f7121;
  --c-shader-gold: #b08a23;

  /* Type */
  --ff: 'Red Hat Display', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --fw-medium: 500;
  --fw-bold: 700;
  --fs-12: 0.75rem;
  --fs-13: 0.8125rem;
  --fs-14: 0.875rem;
  --fs-16: 1rem;
  --fs-21: 1.3125rem;
  --fs-hero: clamp(2.25rem, 1.6rem + 2.2vw, 3.5rem); /* 36 -> 56 px */
  /* 18 -> 21 px: benefit titles, tile eyebrows */
  --fs-lead: clamp(1.125rem, 1rem + 0.5vw, 1.3125rem);
  --fs-tile-title: clamp(1.5rem, 1.1rem + 1.25vw, 2rem); /* 24 -> 32 px */
  --fs-17: 1.0625rem;
  --fs-18: 1.125rem;
  --fs-shader: clamp(2rem, 1.4rem + 1.9vw, 3.25rem); /* 32 -> 52 px */

  /* Motion (CLAUDE.md "Motion") */
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --dur-hover: 250ms;
  --dur-button: 200ms;
  --dur-tile: 500ms;
  --dur-fade: 600ms;
  --dur-zoom: 800ms;
  --dur-move: 500ms; /* menu panel, other movement */
  --slide-interval: 3000ms;
  --dur-flicker: 450ms; /* lamp switch-on flicker (opacity steps) */
  --dur-light-off: 300ms;

  /* Transform amounts. Set to "no effect" under reduced motion below,
     so components never need their own reduced-motion branches for these. */
  --scale-tile-hover: 1.1;
  --scale-slide-in: 1.05;
  --move-menu: 100%;

  /* Layout */
  --container: 1600px;
  --gutter: 16px; /* Figma: px-16 + max-w-1600 on navbar and hero container */
  --radius-pill: 100px;
  --header-h: 80px; /* mobile: 16 + 48 + 16 */

  /* Lamp group in the hero stage (from design/lamp-positions.json):
     left edge 21.7708 %, right edge 80.5209 %, so 58.75 % wide, centred at 51.146 %. */
  --lamps-span: 0.5875;
  --lamps-center: 0.5115;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    /* No transforms (scale, movement). Opacity fades keep their durations. */
    --scale-tile-hover: 1;
    --scale-slide-in: 1;
    --move-menu: 0%;
    --dur-zoom: 0ms;
    --dur-move: 0ms;
  }
}

