/* Fonts: one variable font (wght 300-900) split like Google Fonts does it.
   latin-ext (Polish letters) only downloads when such a character is on the page. */
@font-face {
  font-family: 'Red Hat Display';
  font-style: normal;
  font-weight: 300 900;
  font-display: swap;
  src: url('../assets/fonts/red-hat-display-latin-ext.woff2') format('woff2');
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329,
    U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F,
    U+A720-A7FF;
}

@font-face {
  font-family: 'Red Hat Display';
  font-style: normal;
  font-weight: 300 900;
  font-display: swap;
  src: url('../assets/fonts/red-hat-display-latin.woff2') format('woff2');
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
}

* {
  margin: 0;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-height: 100svh;
  font-family: var(--ff);
  font-weight: var(--fw-medium);
  line-height: 1.2;
  color: var(--c-ink);
  background: var(--c-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img,
svg,
canvas {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

input,
button {
  font: inherit;
  color: inherit;
}

button {
  padding: 0;
  background: none;
  border: 0;
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

:where(ul, ol)[class] {
  padding: 0;
  list-style: none;
}

[hidden] {
  display: none !important;
}

/* Focus: white ring + dark halo, visible on both the dark hero and white sections. */
:focus-visible {
  outline: 2px solid var(--c-white);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--c-black);
}

/* Layout */
.container {
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Button base. Hover colours change through an overlay's opacity (CLAUDE.md
   "Motion"); a variant sets --button-hover-bg to opt in. */
.button {
  position: relative;
  display: inline-flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  padding: 16px 24px;
  overflow: hidden;
  font-size: var(--fs-16);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
  border-radius: var(--radius-pill);
  isolation: isolate;
}

.button::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: '';
  background: var(--button-hover-bg, transparent);
  opacity: 0;
  transition: opacity var(--dur-button) var(--ease);
}

@media (hover: hover) {
  .button:hover::before {
    opacity: 1;
  }
}

.button:focus-visible::before {
  opacity: 1;
}

.button--primary {
  color: var(--c-ink);
  background: var(--c-yellow);
}

/* Black pill; hover: grey #4A4A4A overlay (comments spec 05: 200 ms ease-in-out) */
.button--dark {
  --button-hover-bg: var(--c-grey-hover);

  color: var(--c-white);
  background: var(--c-black);
}

/* Reduced motion: transform amounts are neutralised in tokens.css; this stops
   any remaining keyframe animation. Opacity transitions are left as they are. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

content.content:
1	/* Header (Figma 1:533, PLAN.md §0.3 / §3.2).
2	
3	   One set of markup for both layouts: `.header__menu` wraps nav, search,
4	   configurator and account. From 1280 it is part of the header row; below
5	   1280 it is the burger panel. */
6	.skip-link {
7	  position: absolute;
8	  top: 8px;
9	  left: 8px;
10	  z-index: 100;
11	  padding: 12px 16px;
12	  font-weight: var(--fw-bold);
13	  color: var(--c-ink);
14	  background: var(--c-white);
15	  border-radius: var(--radius-pill);
16	  transform: translateY(-200%);
17	}
18	
19	.skip-link:focus-visible {
20	  transform: none;
21	}
22	
23	.header {
24	  --header-gap: 8px;
25	
26	  position: absolute;
27	  inset: 0 0 auto;
28	  z-index: 10;
29	  color: var(--c-white);
30	  transition: color var(--dur-hover) var(--ease);
31	}
32	
33	/* Solid state (comments spec 02): the white background fades in by opacity;
34	   text, icons and logo follow with a `color` transition (the NOTES.md
35	   exception), same 250 ms ease-in-out both ways. Triggered by mouse hover,
36	   keyboard focus and the open burger panel. */
37	.header::before {
38	  position: absolute;
39	  inset: 0;
40	  content: '';
41	  background: var(--c-white);
42	  opacity: 0;
43	  transition: opacity var(--dur-hover) var(--ease);
44	}
45	
46	.header--open,
47	.header:has(:focus-visible) {
48	  color: var(--c-ink);
49	}
50	
51	.header--open::before,
52	.header:has(:focus-visible)::before {
53	  opacity: 1;
54	}
55	
56	@media (hover: hover) {
57	  .header:hover {
58	    color: var(--c-ink);
59	  }
60	
61	  .header:hover::before {
62	    opacity: 1;
63	  }
64	}
65	
66	/* Stacking context above the white overlay; the mobile panel sits at
67	   z-index -1 inside it, so it stays under the bar but over the overlay. */
68	.header__inner {
69	  position: relative;
70	  z-index: 0;
71	  display: flex;
72	  gap: var(--header-gap);
73	  align-items: center;
74	  justify-content: space-between;
75	  width: min(100% - 2 * var(--gutter), var(--container));
76	  margin-inline: auto;
77	  padding-block: 16px;
78	}
79	
80	.header__logo {
81	  display: flex;
82	  flex: none;
83	  align-items: center;
84	  height: 48px;
85	}
86	
87	.header__actions {
88	  display: flex;
89	  flex: none;
90	  gap: 8px;
91	  align-items: center;
92	}
93	
94	.header__icon,
95	.header__burger {
96	  display: grid;
97	  place-items: center;
98	  width: 48px;
99	  height: 48px;
100	  border-radius: var(--radius-pill);
101	}
102	
103	.header__burger {
104	  align-content: center;
105	  gap: 5px;
106	}
107	
108	/* Burger -> X, in step with the panel slide */
109	.header__burger-line {
110	  display: block;
111	  width: 20px;
112	  height: 2px;
113	  background: currentcolor;
114	  border-radius: 1px;
115	  transition:
116	    transform var(--dur-move) var(--ease),
117	    opacity var(--dur-hover) var(--ease);
118	}
119	
120	.header--open .header__burger-line:nth-child(1) {
121	  transform: translateY(7px) rotate(45deg);
122	}
123	
124	.header--open .header__burger-line:nth-child(2) {
125	  opacity: 0;
126	}
127	
128	.header--open .header__burger-line:nth-child(3) {
129	  transform: translateY(-7px) rotate(-45deg);
130	}
131	
132	.header__link {
133	  display: inline-flex;
134	  gap: 4px;
135	  align-items: center;
136	  font-weight: var(--fw-bold);
137	  line-height: 1.2;
138	  white-space: nowrap;
139	}
140	
141	.header__chevron {
142	  flex: none;
143	}
144	
145	.header__configurator,
146	.header__icon--user {
147	  font-weight: var(--fw-bold);
148	  white-space: nowrap;
149	}
150	
151	.header__configurator svg {
152	  flex: none;
153	}
154	
155	/* Search pill (static, never submits) */
156	.search {
157	  display: flex;
158	  gap: 16px;
159	  align-items: center;
160	  min-width: 0;
161	  padding: 15px 24px; /* + 1 px border = Figma 16 / 24 */
162	  border: 1px solid var(--c-line);
163	  border-radius: var(--radius-pill);
164	}
165	
166	.search:focus-within {
167	  outline: 2px solid var(--c-white);
168	  outline-offset: 2px;
169	  box-shadow: 0 0 0 4px var(--c-black);
170	}
171	
172	.search__input {
173	  flex: 1 1 auto;
174	  min-width: 0;
175	  padding: 0;
176	  font-size: var(--fs-14);
177	  font-weight: var(--fw-bold);
178	  line-height: 1.2;
179	  background: transparent;
180	  border: 0;
181	  appearance: none;
182	}
183	
184	.search__input::placeholder {
185	  color: inherit;
186	  opacity: 1;
187	}
188	
189	.search__input:focus-visible {
190	  outline: none;
191	  box-shadow: none;
192	}
193	
194	.search__input::-webkit-search-cancel-button {
195	  display: none;
196	}
197	
198	.search__button {
199	  display: grid;
200	  flex: none;
201	  place-items: center;
202	}
203	
204	/* Below 1280: burger panel. Full height, slides in from the right with
205	   transform (a plain opacity fade under reduced motion: --move-menu is 0 and
206	   --dur-move 0 ms there). `visibility` keeps the closed panel out of the tab
207	   order; it flips after the slide-out has finished. */
208	@media (width < 1280px) {
209	  html:has(.header--open) {
210	    overflow: hidden;
211	  }
212	
213	  .header__menu {
214	    position: fixed;
215	    inset: 0;
216	    z-index: -1;
217	    display: flex;
218	    flex-direction: column;
219	    gap: 24px;
220	    padding: calc(var(--header-h) + 8px) var(--gutter) 32px;
221	    overflow-y: auto;
222	    overscroll-behavior: contain;
223	    color: var(--c-ink);
224	    visibility: hidden;
225	    background: var(--c-white);
226	    opacity: 0;
227	    transform: translateX(var(--move-menu));
228	    transition:
229	      transform var(--dur-move) var(--ease),
230	      opacity var(--dur-hover) var(--ease),
231	      visibility 0s linear max(var(--dur-move), var(--dur-hover));
232	  }
233	
234	  .header--open .header__menu {
235	    visibility: visible;
236	    opacity: 1;
237	    transform: none;
238	    transition:
239	      transform var(--dur-move) var(--ease),
240	      opacity var(--dur-hover) var(--ease),
241	      visibility 0s;
242	  }
243	
244	  .header__links {
245	    display: flex;
246	    flex-direction: column;
247	  }
248	
249	  .header__link {
250	    justify-content: space-between;
251	    width: 100%;
252	    padding-block: 16px;
253	    font-size: var(--fs-16);
254	    border-bottom: 1px solid var(--c-line);
255	  }
256	
257	  .header__menu-actions {
258	    display: flex;
259	    flex-direction: column;
260	  }
261	
262	  .header__configurator,
263	  .header__icon--user {
264	    display: flex;
265	    gap: 12px;
266	    align-items: center;
267	    width: auto;
268	    height: auto;
269	    padding-block: 12px;
270	    font-size: var(--fs-16);
271	  }
272	
273	  /* same 24 px glyph as the account icon, so the labels line up */
274	  .header__configurator svg {
275	    width: 24px;
276	    height: 24px;
277	  }
278	}
279	
280	/* From 1280: one row. The menu wrapper joins it; its negative end margin
281	   turns the row gap before the cart into the 8 px icon gap from Figma. */
282	@media (width >= 1280px) {
283	  .header {
284	    --header-gap: clamp(16px, 3.33vw, 64px);
285	  }
286	
287	  .header__inner {
288	    justify-content: flex-start;
