/* Header (Figma 1:533, PLAN.md §0.3 / §3.2).

   One set of markup for both layouts: `.header__menu` wraps nav, search,
   configurator and account. From 1280 it is part of the header row; below
   1280 it is the burger panel. */
.skip-link {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 100;
  padding: 12px 16px;
  font-weight: var(--fw-bold);
  color: var(--c-ink);
  background: var(--c-white);
  border-radius: var(--radius-pill);
  transform: translateY(-200%);
}

.skip-link:focus-visible {
  transform: none;
}

.header {
  --header-gap: 8px;

  position: absolute;
  inset: 0 0 auto;
  z-index: 10;
  color: var(--c-white);
  transition: color var(--dur-hover) var(--ease);
}

/* Solid state (comments spec 02): the white background fades in by opacity;
   text, icons and logo follow with a `color` transition (the NOTES.md
   exception), same 250 ms ease-in-out both ways. Triggered by mouse hover,
   keyboard focus and the open burger panel. */
.header::before {
  position: absolute;
  inset: 0;
  content: '';
  background: var(--c-white);
  opacity: 0;
  transition: opacity var(--dur-hover) var(--ease);
}

.header--open,
.header:has(:focus-visible) {
  color: var(--c-ink);
}

.header--open::before,
.header:has(:focus-visible)::before {
  opacity: 1;
}

@media (hover: hover) {
  .header:hover {
    color: var(--c-ink);
  }

  .header:hover::before {
    opacity: 1;
  }
}

/* Stacking context above the white overlay; the mobile panel sits at
   z-index -1 inside it, so it stays under the bar but over the overlay. */
.header__inner {
  position: relative;
  z-index: 0;
  display: flex;
  gap: var(--header-gap);
  align-items: center;
  justify-content: space-between;
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
  padding-block: 16px;
}

.header__logo {
  display: flex;
  flex: none;
  align-items: center;
  height: 48px;
}

.header__actions {
  display: flex;
  flex: none;
  gap: 8px;
  align-items: center;
}

.header__icon,
.header__burger {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-pill);
}

.header__burger {
  align-content: center;
  gap: 5px;
}

/* Burger -> X, in step with the panel slide */
.header__burger-line {
  display: block;
  width: 20px;
  height: 2px;
  background: currentcolor;
  border-radius: 1px;
  transition:
    transform var(--dur-move) var(--ease),
    opacity var(--dur-hover) var(--ease);
}

.header--open .header__burger-line:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.header--open .header__burger-line:nth-child(2) {
  opacity: 0;
}

.header--open .header__burger-line:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.header__link {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
}

.header__chevron {
  flex: none;
}

.header__configurator,
.header__icon--user {
  font-weight: var(--fw-bold);
  white-space: nowrap;
}

.header__configurator svg {
  flex: none;
}

/* Search pill (static, never submits) */
.search {
  display: flex;
  gap: 16px;
  align-items: center;
  min-width: 0;
  padding: 15px 24px; /* + 1 px border = Figma 16 / 24 */
  border: 1px solid var(--c-line);
  border-radius: var(--radius-pill);
}

.search:focus-within {
  outline: 2px solid var(--c-white);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--c-black);
}

.search__input {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0;
  font-size: var(--fs-14);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  background: transparent;
  border: 0;
  appearance: none;
}

.search__input::placeholder {
  color: inherit;
  opacity: 1;
}

.search__input:focus-visible {
  outline: none;
  box-shadow: none;
}

.search__input::-webkit-search-cancel-button {
  display: none;
}

.search__button {
  display: grid;
  flex: none;
  place-items: center;
}

/* Below 1280: burger panel. Full height, slides in from the right with
   transform (a plain opacity fade under reduced motion: --move-menu is 0 and
   --dur-move 0 ms there). `visibility` keeps the closed panel out of the tab
   order; it flips after the slide-out has finished. */
@media (width < 1280px) {
  html:has(.header--open) {
    overflow: hidden;
  }

  .header__menu {
    position: fixed;
    inset: 0;
    z-index: -1;
    display: flex;
    flex-direction: column;
    gap: 24px;
    padding: calc(var(--header-h) + 8px) var(--gutter) 32px;
    overflow-y: auto;
    overscroll-behavior: contain;
    color: var(--c-ink);
    visibility: hidden;
    background: var(--c-white);
    opacity: 0;
    transform: translateX(var(--move-menu));
    transition:
      transform var(--dur-move) var(--ease),
      opacity var(--dur-hover) var(--ease),
      visibility 0s linear max(var(--dur-move), var(--dur-hover));
  }

  .header--open .header__menu {
    visibility: visible;
    opacity: 1;
    transform: none;
    transition:
      transform var(--dur-move) var(--ease),
      opacity var(--dur-hover) var(--ease),
      visibility 0s;
  }

  .header__links {
    display: flex;
    flex-direction: column;
  }

  .header__link {
    justify-content: space-between;
    width: 100%;
    padding-block: 16px;
    font-size: var(--fs-16);
    border-bottom: 1px solid var(--c-line);
  }

  .header__menu-actions {
    display: flex;
    flex-direction: column;
  }

  .header__configurator,
  .header__icon--user {
    display: flex;
    gap: 12px;
    align-items: center;
    width: auto;
    height: auto;
    padding-block: 12px;
    font-size: var(--fs-16);
  }

  /* same 24 px glyph as the account icon, so the labels line up */
  .header__configurator svg {
    width: 24px;
    height: 24px;
  }
}

/* From 1280: one row. The menu wrapper joins it; its negative end margin
   turns the row gap before the cart into the 8 px icon gap from Figma. */
@media (width >= 1280px) {
  .header {
    --header-gap: clamp(16px, 3.33vw, 64px);
  }

  .header__inner {
    justify-content: flex-start;
  }

  .header__menu {
    display: flex;
    flex: 1 1 auto;
    gap: var(--header-gap);
    align-items: center;
    min-width: 0;
    margin-inline-end: calc(8px - var(--header-gap));
  }

  .header__links {
    display: flex;
    gap: clamp(12px, 1.67vw, 32px);
    align-items: center;
  }

  .header__link {
    font-size: var(--fs-14);
  }

  .search {
    flex: 1 1 0;
  }

  .header__menu-actions {
    display: flex;
    flex: none;
    gap: 8px;
    align-items: center;
  }

  .header__configurator {
    display: flex;
    gap: 9px;
    align-items: center;
    padding: 11px 16px;
    font-size: var(--fs-13);
    line-height: 1.1;
    border-radius: var(--radius-pill);
  }

  .header__icon-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .header__burger {
    display: none;
  }
}

/* 1280-1439: the configurator becomes icon-only (its label stays for screen
   readers) so the search pill keeps a usable width. Same 48 px box and 24 px
   glyph as the account and cart icons. */
@media (width >= 1280px) and (width < 1440px) {
  .header__configurator {
    justify-content: center;
    width: 48px;
    height: 48px;
    padding: 0;
  }

  .header__configurator svg {
    width: 24px;
    height: 24px;
  }

  .header__configurator-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

