41	  background: var(--c-white);
42	  opacity: 0;
43	  transition: opacity var(--dur-hover) var(--ease);
44	}
45	
46	.header--open,
47	.header:has(:focus-visible) {
48	  color: var(--c-ink);
49	}
50	
51	.header--open::before,
52	.header:has(:focus-visible)::before {
53	  opacity: 1;
54	}
55	
56	@media (hover: hover) {
57	  .header:hover {
58	    color: var(--c-ink);
59	  }
60	
61	  .header:hover::before {
62	    opacity: 1;
63	  }
64	}
65	
66	/* Stacking context above the white overlay; the mobile panel sits at
67	   z-index -1 inside it, so it stays under the bar but over the overlay. */
68	.header__inner {
69	  position: relative;
70	  z-index: 0;
71	  display: flex;
72	  gap: var(--header-gap);
73	  align-items: center;
74	  justify-content: space-between;
75	  width: min(100% - 2 * var(--gutter), var(--container));
76	  margin-inline: auto;
77	  padding-block: 16px;
78	}
79	
80	.header__logo {
81	  display: flex;
82	  flex: none;
83	  align-items: center;
84	  height: 48px;
85	}
86	
87	.header__actions {
88	  display: flex;
89	  flex: none;
90	  gap: 8px;
91	  align-items: center;
92	}
93	
94	.header__icon,
95	.header__burger {
96	  display: grid;
97	  place-items: center;
98	  width: 48px;
99	  height: 48px;
100	  border-radius: var(--radius-pill);
101	}
102	
103	.header__burger {
104	  align-content: center;
105	  gap: 5px;
106	}
107	
108	/* Burger -> X, in step with the panel slide */
109	.header__burger-line {
110	  display: block;
111	  width: 20px;
112	  height: 2px;
113	  background: currentcolor;
114	  border-radius: 1px;
115	  transition:
116	    transform var(--dur-move) var(--ease),
117	    opacity var(--dur-hover) var(--ease);
118	}
119	
120	.header--open .header__burger-line:nth-child(1) {
121	  transform: translateY(7px) rotate(45deg);
122	}
123	
124	.header--open .header__burger-line:nth-child(2) {
125	  opacity: 0;
126	}
127	
128	.header--open .header__burger-line:nth-child(3) {
129	  transform: translateY(-7px) rotate(-45deg);
130	}
131	
132	.header__link {
133	  display: inline-flex;
134	  gap: 4px;
135	  align-items: center;
136	  font-weight: var(--fw-bold);
137	  line-height: 1.2;
138	  white-space: nowrap;
139	}
140	
141	.header__chevron {
142	  flex: none;
143	}
144	
145	.header__configurator,
146	.header__icon--user {
147	  font-weight: var(--fw-bold);
148	  white-space: nowrap;
149	}
150	
151	.header__configurator svg {
152	  flex: none;
153	}
154	
155	/* Search pill (static, never submits) */
156	.search {
157	  display: flex;
158	  gap: 16px;
159	  align-items: center;
160	  min-width: 0;
161	  padding: 15px 24px; /* + 1 px border = Figma 16 / 24 */
162	  border: 1px solid var(--c-line);
163	  border-radius: var(--radius-pill);
164	}
165	
166	.search:focus-within {
167	  outline: 2px solid var(--c-white);
168	  outline-offset: 2px;
169	  box-shadow: 0 0 0 4px var(--c-black);
170	}
171	
172	.search__input {
173	  flex: 1 1 auto;
174	  min-width: 0;
175	  padding: 0;
176	  font-size: var(--fs-14);
177	  font-weight: var(--fw-bold);
178	  line-height: 1.2;
179	  background: transparent;
180	  border: 0;
181	  appearance: none;
182	}
183	
184	.search__input::placeholder {
185	  color: inherit;
186	  opacity: 1;
187	}
188	
189	.search__input:focus-visible {
190	  outline: none;
191	  box-shadow: none;
192	}
193	
194	.search__input::-webkit-search-cancel-button {
195	  display: none;
196	}
197	
198	.search__button {
199	  display: grid;
200	  flex: none;
201	  place-items: center;
202	}
203	
204	/* Below 1280: burger panel. Full height, slides in from the right with
205	   transform (a plain opacity fade under reduced motion: --move-menu is 0 and
206	   --dur-move 0 ms there). `visibility` keeps the closed panel out of the tab
207	   order; it flips after the slide-out has finished. */
208	@media (width < 1280px) {
209	  html:has(.header--open) {
210	    overflow: hidden;
211	  }
212	
213	  .header__menu {
214	    position: fixed;
215	    inset: 0;
216	    z-index: -1;
217	    display: flex;
218	    flex-direction: column;
219	    gap: 24px;
220	    padding: calc(var(--header-h) + 8px) var(--gutter) 32px;
221	    overflow-y: auto;
222	    overscroll-behavior: contain;
223	    color: var(--c-ink);
224	    visibility: hidden;
225	    background: var(--c-white);
226	    opacity: 0;
227	    transform: translateX(var(--move-menu));
228	    transition:
229	      transform var(--dur-move) var(--ease),
230	      opacity var(--dur-hover) var(--ease),
231	      visibility 0s linear max(var(--dur-move), var(--dur-hover));
232	  }
233	
234	  .header--open .header__menu {
235	    visibility: visible;
236	    opacity: 1;
237	    transform: none;
238	    transition:
239	      transform var(--dur-move) var(--ease),
240	      opacity var(--dur-hover) var(--ease),
241	      visibility 0s;
242	  }
243	
244	  .header__links {
245	    display: flex;
246	    flex-direction: column;
247	  }
248	
249	  .header__link {
250	    justify-content: space-between;
251	    width: 100%;
252	    padding-block: 16px;
253	    font-size: var(--fs-16);
254	    border-bottom: 1px solid var(--c-line);
255	  }
256	
257	  .header__menu-actions {
258	    display: flex;
259	    flex-direction: column;
260	  }
261	
262	  .header__configurator,
263	  .header__icon--user {
264	    display: flex;
265	    gap: 12px;
266	    align-items: center;
267	    width: auto;
268	    height: auto;
269	    padding-block: 12px;
270	    font-size: var(--fs-16);
271	  }
272	
273	  /* same 24 px glyph as the account icon, so the labels line up */
274	  .header__configurator svg {
275	    width: 24px;
276	    height: 24px;
277	  }
278	}
279	
280	/* From 1280: one row. The menu wrapper joins it; its negative end margin
281	   turns the row gap before the cart into the 8 px icon gap from Figma. */
282	@media (width >= 1280px) {
283	  .header {
284	    --header-gap: clamp(16px, 3.33vw, 64px);
285	  }
286	
287	  .header__inner {
288	    justify-content: flex-start;
289	  }
290	
291	  .header__menu {
292	    display: flex;
293	    flex: 1 1 auto;
294	    gap: var(--header-gap);
295	    align-items: center;
296	    min-width: 0;
297	    margin-inline-end: calc(8px - var(--header-gap));
298	  }
299	
300	  .header__links {
301	    display: flex;
302	    gap: clamp(12px, 1.67vw, 32px);
303	    align-items: center;
304	  }
305	
306	  .header__link {
307	    font-size: var(--fs-14);
308	  }
309	
310	  .search {
311	    flex: 1 1 0;
312	  }
313	
314	  .header__menu-actions {
315	    display: flex;
316	    flex: none;
317	    gap: 8px;
318	    align-items: center;
319	  }
320	
321	  .header__configurator {
322	    display: flex;
323	    gap: 9px;
324	    align-items: center;
325	    padding: 11px 16px;
326	    font-size: var(--fs-13);
327	    line-height: 1.1;
328	    border-radius: var(--radius-pill);
329	  }
330	
331	  .header__icon-label {
332	    position: absolute;
333	    width: 1px;
334	    height: 1px;
335	    overflow: hidden;
336	    clip-path: inset(50%);
337	    white-space: nowrap;
338	  }
339	
340	  .header__burger {
341	    display: none;
342	  }
343	}
344	
345	/* 1280-1439: the configurator becomes icon-only (its label stays for screen
346	   readers) so the search pill keeps a usable width. Same 48 px box and 24 px
347	   glyph as the account and cart icons. */
348	@media (width >= 1280px) and (width < 1440px) {
349	  .header__configurator {
350	    justify-content: center;
351	    width: 48px;
352	    height: 48px;
353	    padding: 0;
354	  }
355	
356	  .header__configurator svg {
357	    width: 24px;
358	    height: 24px;
359	  }
360	
361	  .header__configurator-label {
362	    position: absolute;
363	    width: 1px;
364	    height: 1px;
365	    overflow: hidden;
366	    clip-path: inset(50%);
367	    white-space: nowrap;
368	  }
369	}
