/* Hero (Figma 1:506, PLAN.md §0.3 / §3.3 / §3.4).

   Two layouts share one rule: everything that must stay aligned with the photo
   (slide images and lamps) lives in a `.hero__stage` box with the photo's
   1920:1080 ratio, positioned identically.

   - Cover mode (landscape): the stage covers the hero like object-fit: cover.
   - Contained mode (portrait, max-aspect-ratio 5/4): covering would crop the
     lamps, so the stage is sized so the lamp group fits the viewport width and
     sits at the bottom. Above it, the slide's own sky colour (sampled from the
     photo's top edge) continues the image; the stage's top edge fades into it. */
.hero {
  --hero-h: clamp(560px, 100svh, 1080px);

  /* only ever used for `width`: the 100% must resolve against the hero's width */
  --stage-w: max(100%, var(--hero-h) * 16 / 9);
  --arrow-size: 48px;
  --arrow-inset: 72px;

  /* while the arrows show, text starts this far from the hero edge
     (inset + arrow + 24 px gap); at 1920 the 1600 column is wider anyway */
  --arrow-clear: calc(var(--arrow-inset) + var(--arrow-size) + 24px);

  position: relative;
  display: grid;
  height: var(--hero-h);
  overflow: hidden;
  color: var(--c-white);
  background: var(--c-black);

  /* horizontal swipes go to the slider (js/hero-slider.js), vertical ones scroll */
  touch-action: pan-y;
}

.hero__slides {
  position: absolute;
  inset: 0;
}

/* Crossfade (comments spec 04): 600 ms ease-in-out, both ways. */
.hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity var(--dur-fade) var(--ease);
}

.hero__slide--active {
  opacity: 1;
}

/* Top-edge colour of each photo; scrim keeps white text >= 4.5:1 on mobile */
.hero__slide--rock {
  --hero-sky: #9c6744;
  --hero-scrim: 0%;
}

.hero__slide--interior {
  --hero-sky: #c5afa3;
  --hero-scrim: 45%;
}

/* Height comes from aspect-ratio, never from a calc on --stage-w: inside
   `height`, the 100% in --stage-w would resolve against the hero's height and
   squash the photo on viewports wider than 16:9 (e.g. 1280 x 633). */
.hero__stage {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--stage-w);
  aspect-ratio: 1920 / 1080;
  transform: translate(-50%, -50%);
}

/* Incoming image zooms 1.05 -> 1 over 800 ms ease-out. An inactive image
   waits at 1.05, but only snaps there after its own fade-out has finished,
   so the outgoing slide never jumps. */
.hero__img {
  width: 100%;
  height: 100%;
  scale: var(--scale-slide-in);
  transition: scale 0s linear var(--dur-fade);
}

.hero__slide--active .hero__img {
  scale: 1;
  transition: scale var(--dur-zoom) var(--ease-out);
}

/* Lamps */
.hero__stage--lamps {
  z-index: 1;
}

.lamp {
  position: absolute;
  top: var(--y);
  left: var(--x);
  width: var(--w);
}

/* Neither photo has lamps in it, so the lamp images are always visible and
   never fade or zoom: only the backgrounds crossfade and zoom underneath. */
.lamp__img {
  width: 100%;
}

/* Text block: grid item on top of the absolute layers */
.hero__content {
  z-index: 2;
  grid-area: 1 / 1;
  align-self: center;
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
  padding-block: 64px;
  pointer-events: none;
}

.hero__inner {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.hero__inner > * {
  pointer-events: auto;
}

.hero__eyebrow {
  font-size: var(--fs-16);
  font-weight: var(--fw-medium);
  line-height: 1.2;
}

.hero__title {
  margin-top: 16px;
  font-size: var(--fs-hero);
  font-weight: var(--fw-bold);
  line-height: 1;
}

.hero__cta {
  margin-top: 32px;
}

/* Trustmate badge: bottom right of the hero on desktop (absolute against
   .hero, since .hero__content is not positioned), in the text flow on mobile. */
.hero__badge {
  display: inline-flex;
  gap: 12px;
  align-items: center;
  margin-top: 24px;
  padding: 12px 24px;
  font-size: var(--fs-13);
  font-weight: var(--fw-medium);
  line-height: 1.1;
  white-space: nowrap;
  background: var(--c-badge-bg);
  border-radius: var(--radius-pill);
}

.hero__rating {
  display: inline-flex;
  gap: 2px;
  align-items: center;
  font-size: var(--fs-21);
  font-weight: var(--fw-bold);
}

/* Arrows: hidden below 1024 (PLAN.md §5, proposed) */
.hero__arrow {
  position: absolute;
  top: 50%;
  z-index: 3;
  display: none;
  place-items: center;
  width: var(--arrow-size);
  height: var(--arrow-size);
  color: var(--c-line);
  background: var(--c-control-bg);
  border-radius: var(--radius-pill);
  transform: translateY(-50%);
  isolation: isolate;
}

/* Hover (not in the design; simplest consistent option): a second layer of
   the same translucent black fades in, as with the buttons' overlay. */
.hero__arrow::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: '';
  background: var(--c-control-bg);
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--dur-button) var(--ease);
}

@media (hover: hover) {
  .hero__arrow:hover::before {
    opacity: 1;
  }
}

.hero__arrow--prev {
  left: var(--arrow-inset);
}

.hero__arrow--next {
  right: var(--arrow-inset);
}

/* Progress: 2 x 64 x 2 px bars; the buttons are 44 px tall tap targets.
   While autoplaying, js/hero-slider.js sets the active fill's scaleX every
   frame (linear over --slide-interval). Without autoplay (reduced motion, no
   JS) the active bar is simply full. */
.hero__progress {
  position: absolute;
  bottom: 11px; /* 32 px to the bar = 11 + (44 - 2) / 2 */
  left: 50%;
  z-index: 3;
  display: flex;
  gap: 4px;
  transform: translateX(-50%);
}

.hero__dot {
  position: relative;
  width: 64px;
  height: 44px;
}

.hero__dot::before,
.hero__dot-fill {
  position: absolute;
  inset: 21px 0;
}

.hero__dot::before {
  content: '';
  background: var(--c-track);
}

.hero__dot-fill {
  background: var(--c-yellow);
  transform: scaleX(0);
  transform-origin: left;
}

.hero__dot--active .hero__dot-fill {
  transform: scaleX(1);
}

/* Pause/play toggle (WCAG 2.2.2): styled like the bar, white icon, no
   background. Sits just right of the segments, outside the centred group, so
   the segments stay centred. 44 x 44 tap target. aria-pressed="true" means
   paused, so the icon switches to "play". */
.hero__pause {
  position: absolute;
  top: 0;
  left: calc(100% + 4px);
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  color: var(--c-white);
}

.hero__pause[hidden] {
  display: none;
}

.hero__pause[aria-pressed='true'] .hero__pause-icon--pause,
.hero__pause[aria-pressed='false'] .hero__pause-icon--play {
  display: none;
}

@media (width >= 1024px) {
  .hero__arrow {
    display: grid;
  }

  .hero__content {
    width: min(100% - 2 * var(--arrow-clear), var(--container));
  }

  .hero__badge {
    position: absolute;
    right: var(--arrow-inset);
    bottom: 32px;
    z-index: 3;
    margin: 0;
  }
}

/* Contained mode: portrait screens */
@media (max-aspect-ratio: 5/4) {
  .hero {
    /* no % here, so --stage-h can be derived from it */
    --stage-w: calc((100vw - 2 * var(--gutter)) / var(--lamps-span));
    --stage-h: calc(var(--stage-w) * 9 / 16);

    height: auto;
    min-height: var(--hero-h);
  }

  .hero__slide {
    background: var(--hero-sky);
  }

  .hero__slide::after {
    position: absolute;
    inset: 0 0 auto;
    height: calc(100% - var(--stage-h) * 0.8);
    content: '';
    background: linear-gradient(rgb(16 16 17 / var(--hero-scrim)) 60%, rgb(16 16 17 / 0%));
  }

  .hero__stage {
    top: auto;
    bottom: 0;

    /* centre the lamp group, not the photo */
    left: calc(50% - var(--stage-w) * var(--lamps-center));
    transform: none;
  }

  .hero__img {
    mask-image: linear-gradient(transparent, #000 25%);
  }

  .hero__content {
    align-self: start;

    /* room for the header on top and for the stage below; the stage's top
       8 % is sky, so the text may overlap that */
    padding-top: calc(var(--header-h) + 24px);
    padding-bottom: calc(var(--stage-h) * 0.92 + 24px);
  }
}

