391	}
392	
393	/* Reduced motion: no flicker and no pulse; switching is a plain fade */
394	@media (prefers-reduced-motion: reduce) {
395	  .light--on .light__glow {
396	    animation: none;
397	  }
398	
399	  .light__glow {
400	    transition-duration: var(--dur-fade);
401	  }
402	
403	  .hero__hint-dot::after {
404	    animation: none;
405	    opacity: 0;
406	  }
407	}
