1	/* Hero (Figma 1:506, PLAN.md §0.3 / §3.3 / §3.4).
2	
3	   Two layouts share one rule: everything that must stay aligned with the photo
4	   (slide images and lamps) lives in a `.hero__stage` box with the photo's
5	   1920:1080 ratio, positioned identically.
6	
7	   - Cover mode (landscape): the stage covers the hero like object-fit: cover.
8	   - Contained mode (portrait, max-aspect-ratio 5/4): covering would crop the
9	     lamps, so the stage is sized so the lamp group fits the viewport width and
10	     sits at the bottom. Above it, the slide's own sky colour (sampled from the
11	     photo's top edge) continues the image; the stage's top edge fades into it. */
12	.hero {
13	  --hero-h: clamp(560px, 100svh, 1080px);
14	
15	  /* only ever used for `width`: the 100% must resolve against the hero's width */
16	  --stage-w: max(100%, var(--hero-h) * 16 / 9);
17	  --arrow-size: 48px;
18	  --arrow-inset: 72px;
19	
20	  /* while the arrows show, text starts this far from the hero edge
21	     (inset + arrow + 24 px gap); at 1920 the 1600 column is wider anyway */
22	  --arrow-clear: calc(var(--arrow-inset) + var(--arrow-size) + 24px);
23	
24	  position: relative;
25	  display: grid;
26	  height: var(--hero-h);
27	  overflow: hidden;
28	  color: var(--c-white);
29	  background: var(--c-black);
30	
31	  /* horizontal swipes go to the slider (js/hero-slider.js), vertical ones scroll */
32	  touch-action: pan-y;
33	}
34	
35	.hero__slides {
36	  position: absolute;
37	  inset: 0;
38	}
39	
40	/* Crossfade (comments spec 04): 600 ms ease-in-out, both ways. */
41	.hero__slide {
42	  position: absolute;
43	  inset: 0;
44	  opacity: 0;
45	  transition: opacity var(--dur-fade) var(--ease);
46	}
47	
48	.hero__slide--active {
49	  opacity: 1;
50	}
51	
52	/* Top-edge colour of each photo; scrim keeps white text >= 4.5:1 on mobile */
53	.hero__slide--rock {
54	  --hero-sky: #9c6744;
55	  --hero-scrim: 0%;
56	}
57	
58	.hero__slide--interior {
59	  --hero-sky: #c5afa3;
60	  --hero-scrim: 45%;
61	}
62	
63	/* Height comes from aspect-ratio, never from a calc on --stage-w: inside
64	   `height`, the 100% in --stage-w would resolve against the hero's height and
65	   squash the photo on viewports wider than 16:9 (e.g. 1280 x 633). */
66	.hero__stage {
67	  position: absolute;
68	  top: 50%;
69	  left: 50%;
70	  width: var(--stage-w);
71	  aspect-ratio: 1920 / 1080;
72	  transform: translate(-50%, -50%);
73	}
74	
75	/* Incoming image zooms 1.05 -> 1 over 800 ms ease-out. An inactive image
76	   waits at 1.05, but only snaps there after its own fade-out has finished,
77	   so the outgoing slide never jumps. */
78	.hero__img {
79	  width: 100%;
80	  height: 100%;
81	  scale: var(--scale-slide-in);
82	  transition: scale 0s linear var(--dur-fade);
83	}
84	
85	.hero__slide--active .hero__img {
86	  scale: 1;
87	  transition: scale var(--dur-zoom) var(--ease-out);
88	}
89	
90	/* Lamps */
91	.hero__stage--lamps {
92	  z-index: 1;
93	}
94	
95	.lamp {
96	  position: absolute;
97	  top: var(--y);
98	  left: var(--x);
99	  width: var(--w);
100	}
101	
102	/* Neither photo has lamps in it, so the lamp images are always visible and
103	   never fade or zoom: only the backgrounds crossfade and zoom underneath. */
104	.lamp__img {
105	  width: 100%;
106	}
107	
108	/* Text block: grid item on top of the absolute layers */
109	.hero__content {
110	  z-index: 2;
111	  grid-area: 1 / 1;
112	  align-self: center;
113	  width: min(100% - 2 * var(--gutter), var(--container));
114	  margin-inline: auto;
115	  padding-block: 64px;
116	  pointer-events: none;
117	}
118	
119	.hero__inner {
120	  display: flex;
121	  flex-direction: column;
122	  align-items: flex-start;
123	}
124	
125	.hero__inner > * {
126	  pointer-events: auto;
127	}
128	
129	.hero__eyebrow {
130	  font-size: var(--fs-16);
131	  font-weight: var(--fw-medium);
132	  line-height: 1.2;
133	}
134	
135	.hero__title {
136	  margin-top: 16px;
137	  font-size: var(--fs-hero);
138	  font-weight: var(--fw-bold);
139	  line-height: 1;
140	}
141	
142	.hero__cta {
143	  margin-top: 32px;
144	}
145	
146	/* Trustmate badge: bottom right of the hero on desktop (absolute against
147	   .hero, since .hero__content is not positioned), in the text flow on mobile. */
148	.hero__badge {
149	  display: inline-flex;
150	  gap: 12px;
151	  align-items: center;
152	  margin-top: 24px;
153	  padding: 12px 24px;
154	  font-size: var(--fs-13);
155	  font-weight: var(--fw-medium);
156	  line-height: 1.1;
157	  white-space: nowrap;
158	  background: var(--c-badge-bg);
159	  border-radius: var(--radius-pill);
160	}
161	
162	.hero__rating {
163	  display: inline-flex;
164	  gap: 2px;
165	  align-items: center;
166	  font-size: var(--fs-21);
167	  font-weight: var(--fw-bold);
168	}
169	
170	/* Arrows: hidden below 1024 (PLAN.md §5, proposed) */
171	.hero__arrow {
172	  position: absolute;
173	  top: 50%;
174	  z-index: 3;
175	  display: none;
176	  place-items: center;
177	  width: var(--arrow-size);
178	  height: var(--arrow-size);
179	  color: var(--c-line);
180	  background: var(--c-control-bg);
181	  border-radius: var(--radius-pill);
182	  transform: translateY(-50%);
183	  isolation: isolate;
184	}
185	
186	/* Hover (not in the design; simplest consistent option): a second layer of
187	   the same translucent black fades in, as with the buttons' overlay. */
188	.hero__arrow::before {
189	  position: absolute;
190	  inset: 0;
191	  z-index: -1;
192	  content: '';
193	  background: var(--c-control-bg);
194	  border-radius: inherit;
195	  opacity: 0;
196	  transition: opacity var(--dur-button) var(--ease);
197	}
198	
199	@media (hover: hover) {
200	  .hero__arrow:hover::before {
201	    opacity: 1;
202	  }
203	}
204	
205	.hero__arrow--prev {
206	  left: var(--arrow-inset);
207	}
208	
209	.hero__arrow--next {
210	  right: var(--arrow-inset);
211	}
212	
213	/* Progress: 2 x 64 x 2 px bars; the buttons are 44 px tall tap targets.
214	   While autoplaying, js/hero-slider.js sets the active fill's scaleX every
215	   frame (linear over --slide-interval). Without autoplay (reduced motion, no
216	   JS) the active bar is simply full. */
217	.hero__progress {
218	  position: absolute;
219	  bottom: 11px; /* 32 px to the bar = 11 + (44 - 2) / 2 */
220	  left: 50%;
221	  z-index: 3;
222	  display: flex;
223	  gap: 4px;
224	  transform: translateX(-50%);
225	}
226	
227	.hero__dot {
228	  position: relative;
229	  width: 64px;
230	  height: 44px;
231	}
232	
233	.hero__dot::before,
234	.hero__dot-fill {
235	  position: absolute;
236	  inset: 21px 0;
237	}
238	
239	.hero__dot::before {
240	  content: '';
241	  background: var(--c-track);
242	}
243	
244	.hero__dot-fill {
245	  background: var(--c-yellow);
246	  transform: scaleX(0);
247	  transform-origin: left;
248	}
249	
250	.hero__dot--active .hero__dot-fill {
251	  transform: scaleX(1);
252	}
253	
254	/* Pause/play toggle (WCAG 2.2.2): styled like the bar, white icon, no
255	   background. Sits just right of the segments, outside the centred group, so
256	   the segments stay centred. 44 x 44 tap target. aria-pressed="true" means
257	   paused, so the icon switches to "play". */
258	.hero__pause {
259	  position: absolute;
260	  top: 0;
261	  left: calc(100% + 4px);
262	  display: grid;
263	  place-items: center;
264	  width: 44px;
265	  height: 44px;
266	  color: var(--c-white);
267	}
268	
269	.hero__pause[hidden] {
270	  display: none;
271	}
272	
273	.hero__pause[aria-pressed='true'] .hero__pause-icon--pause,
274	.hero__pause[aria-pressed='false'] .hero__pause-icon--play {
275	  display: none;
276	}
277	
278	@media (width >= 1024px) {
279	  .hero__arrow {
280	    display: grid;
281	  }
282	
283	  .hero__content {
284	    width: min(100% - 2 * var(--arrow-clear), var(--container));
285	  }
286	
287	  .hero__badge {
288	    position: absolute;
289	    right: var(--arrow-inset);
290	    bottom: 32px;
291	    z-index: 3;
292	    margin: 0;
293	  }
294	}
295	
296	/* Contained mode: portrait screens */
297	@media (max-aspect-ratio: 5/4) {
298	  .hero {
299	    /* no % here, so --stage-h can be derived from it */
300	    --stage-w: calc((100vw - 2 * var(--gutter)) / var(--lamps-span));
301	    --stage-h: calc(var(--stage-w) * 9 / 16);
302	
303	    height: auto;
304	    min-height: var(--hero-h);
305	  }
306	
307	  .hero__slide {
308	    background: var(--hero-sky);
309	  }
310	
311	  .hero__slide::after {
312	    position: absolute;
313	    inset: 0 0 auto;
314	    height: calc(100% - var(--stage-h) * 0.8);
315	    content: '';
316	    background: linear-gradient(rgb(16 16 17 / var(--hero-scrim)) 60%, rgb(16 16 17 / 0%));
317	  }
318	
319	  .hero__stage {
320	    top: auto;
321	    bottom: 0;
322	
323	    /* centre the lamp group, not the photo */
324	    left: calc(50% - var(--stage-w) * var(--lamps-center));
325	    transform: none;
326	  }
327	
328	  .hero__img {
329	    mask-image: linear-gradient(transparent, #000 25%);
330	  }
331	
332	  .hero__content {
333	    align-self: start;
334	
335	    /* room for the header on top and for the stage below; the stage's top
336	       8 % is sky, so the text may overlap that */
337	    padding-top: calc(var(--header-h) + 24px);
338	    padding-bottom: calc(var(--stage-h) * 0.92 + 24px);
339	  }
340	}
