1	/* Lamp light (PLAN.md §3.3, comments spec 03; option B with a light dim).
2	
3	   Layers, bottom to top: slides -> lamps (buttons) -> .hero__dim ->
4	   .hero__stage--light -> text. The light stage has the same 1920:1080
5	   geometry as the photo, so every shape below is placed in % of the stage
6	   (positions read from the lamp PNGs) and scales with it at every width.
7	
8	   Motion rules: only `.light__glow` (per lamp), `.light__peek`, the dim and
9	   the headline glow animate, and only their opacity. The blurred / clipped
10	   shapes inside never change, so they rasterise once. The screen blend sits
11	   on the light stage, which itself never animates. */
12	
13	/* Room dim: none with no lamps on, then a little deeper per lamp */
14	.hero__dim {
15	  position: absolute;
16	  inset: 0;
17	  z-index: 1;
18	  pointer-events: none;
19	  background: var(--c-black);
20	  opacity: 0;
21	  transition: opacity var(--dur-fade) var(--ease);
22	}
23	
24	.hero--lit-1 .hero__dim {
25	  opacity: var(--lamp-dim-1);
26	}
27	
28	.hero--lit-2 .hero__dim {
29	  opacity: var(--lamp-dim-2);
30	}
31	
32	.hero--lit-3 .hero__dim {
33	  opacity: var(--lamp-dim-3);
34	}
35	
36	/* Hidden while unused: a blended layer on the page switches nearby text from
37	   sub-pixel to greyscale anti-aliasing, so with no lamp on, hovered or
38	   focused the hero would not be pixel-identical to the design. It turns
39	   visible instantly and hides only after the switch-off fade. */
40	.hero__stage--light {
41	  z-index: 1;
42	  pointer-events: none;
43	  visibility: hidden;
44	  mix-blend-mode: screen;
45	  transition: visibility 0s linear var(--dur-fade);
46	}
