119	  --dw: 13.02%;
120	  --dh: 12.04%;
121	  --rot: -20deg;
122	  --cone-angle: 60deg;
123	  --cone-len: 10.94%;
124	  --cone-w: 21.3%;
125	  --px: 41.67%;
126	  --py: 79.81%;
127	  --pw: 13.54%;
128	  --ph: 5.56%;
129	}
130	
131	.light__peek,
132	.light__disc,
133	.light__halo,
134	.light__cone,
135	.light__pool {
136	  position: absolute;
137	}
138	
139	/* Diffuser: the disc of light inside the lamp opening */
140	.light__peek,
141	.light__disc {
142	  top: calc(var(--cy) - var(--dh) / 2);
143	  left: calc(var(--cx) - var(--dw) / 2);
144	  width: var(--dw);
145	  height: var(--dh);
146	  background: radial-gradient(
147	    closest-side,
148	    var(--c-light-core) 0%,
149	    var(--c-light-warm) 45%,
150	    rgb(255 196 110 / 55%) 75%,
151	    rgb(255 170 80 / 0%) 100%
152	  );
153	  border-radius: 50%;
154	  transform: rotate(var(--rot));
155	}
156	
157	/* Discoverability: a faint glow on hover / keyboard focus while off */
158	.light__peek {
159	  opacity: 0;
160	  transition: opacity var(--dur-hover) var(--ease);
161	}
162	
163	@media (hover: hover) {
164	  .hero:has(.lamp--1:hover) .light--1 .light__peek,
165	  .hero:has(.lamp--2:hover) .light--2 .light__peek,
166	  .hero:has(.lamp--3:hover) .light--3 .light__peek {
167	    opacity: 0.35;
168	  }
169	}
170	
171	.hero:has(.lamp--1:focus-visible) .light--1 .light__peek,
172	.hero:has(.lamp--2:focus-visible) .light--2 .light__peek,
173	.hero:has(.lamp--3:focus-visible) .light--3 .light__peek {
174	  opacity: 0.35;
175	}
176	
177	.light--on .light__peek {
178	  opacity: 0;
179	}
180	
181	/* The light itself: one group per lamp. On: a short flicker, then steady.
182	   Off: a plain fade. */
183	.light__glow {
184	  position: absolute;
185	  inset: 0;
186	  opacity: 0;
187	  transition: opacity var(--dur-light-off) var(--ease);
188	}
189	
190	.light--on .light__glow {
191	  opacity: 1;
192	  animation: lamp-flicker var(--dur-flicker) linear;
193	}
194	
195	@keyframes lamp-flicker {
196	  0% {
197	    opacity: 0;
198	  }
199	
200	  12% {
201	    opacity: 0.7;
202	  }
203	
204	  22% {
205	    opacity: 0.15;
206	  }
207	
208	  38% {
209	    opacity: 0.9;
210	  }
211	
212	  50% {
213	    opacity: 0.35;
214	  }
215	
216	  70% {
217	    opacity: 1;
218	  }
219	
220	  82% {
221	    opacity: 0.75;
222	  }
223	
224	  100% {
225	    opacity: 1;
226	  }
227	}
228	
229	.light__halo {
230	  top: calc(var(--cy) - var(--dh) * 0.95);
231	  left: calc(var(--cx) - var(--dw) * 0.95);
232	  width: calc(var(--dw) * 1.9);
233	  height: calc(var(--dh) * 1.9);
234	  background: radial-gradient(
235	    closest-side,
236	    rgb(255 190 110 / 75%),
237	    rgb(255 150 70 / 25%) 55%,
238	    rgb(255 140 60 / 0%) 100%
239	  );
240	  border-radius: 50%;
241	  opacity: 0.45;
242	  filter: blur(clamp(3px, 0.3vw, 6px));
243	  transform: rotate(var(--rot));
244	}
245	
246	/* Cone: blurred on the outer box, clipped to a wedge on the inner one
247	   (clip-path applies after filter, so they can't share an element). */
248	.light__cone {
249	  top: calc(var(--cy) - var(--cone-w) / 2);
250	  left: var(--cx);
251	  width: var(--cone-len);
252	  height: var(--cone-w);
253	  opacity: 0.62;
254	  filter: blur(clamp(6px, 0.95vw, 18px));
255	  transform: rotate(var(--cone-angle));
256	  transform-origin: 0 50%;
257	}
258	
259	.light__cone::before {
260	  position: absolute;
261	  inset: 0;
262	  content: '';
263	  background: linear-gradient(
264	    to right,
265	    rgb(255 214 150 / 90%),
266	    rgb(255 190 110 / 45%) 45%,
267	    rgb(255 170 90 / 0%)
268	  );
269	  clip-path: polygon(0 40%, 100% 0, 100% 100%, 0 60%);
270	}
271	
272	/* Warm light where the cone lands on the rock (slide 1 only: slide 2 has no
273	   rock, so the pools fade out with the crossfade). */
274	.light__pool {
275	  top: calc(var(--py) - var(--ph) / 2);
276	  left: calc(var(--px) - var(--pw) / 2);
277	  width: var(--pw);
278	  height: var(--ph);
279	  background: radial-gradient(
280	    closest-side,
281	    rgb(255 180 100 / 90%),
282	    rgb(255 150 70 / 35%) 55%,
283	    rgb(255 140 60 / 0%)
284	  );
285	  border-radius: 50%;
286	  opacity: 0.5;
287	  filter: blur(clamp(3px, 0.42vw, 8px));
288	  transition: opacity var(--dur-fade) var(--ease);
289	
290	  /* parallax: pulled back towards rest (see "Cursor parallax" above) */
291	  translate: var(--parallax-pool, none);
292	}
293	
294	.hero:has(.hero__slide--interior.hero__slide--active) .light__pool {
295	  opacity: 0;
296	}
297	
298	/* First-visit hint next to lamp 2 (gone after the first click, remembered) */
299	.hero__hint {
300	  position: absolute;
301	  top: 52%;
302	  left: 81.25%;
303	  z-index: 1;
304	  display: flex;
305	  gap: 8px;
306	  align-items: center;
307	  padding: 8px 14px;
308	  font-size: var(--fs-13);
309	  font-weight: var(--fw-medium);
310	  line-height: 1.1;
311	  color: var(--c-white);
312	  white-space: nowrap;
313	  pointer-events: none;
314	  background: var(--c-badge-bg);
315	  border-radius: var(--radius-pill);
316	  animation: hint-in var(--dur-fade) var(--ease) 1.2s both;
317	}
318	
319	.hero__hint[hidden] {
320	  display: none;
321	}
322	
323	.hero__hint-dot {
324	  position: relative;
325	  width: 8px;
326	  height: 8px;
327	  background: var(--c-yellow);
328	  border-radius: 50%;
329	}
330	
331	.hero__hint-dot::after {
332	  position: absolute;
333	  inset: 0;
334	  content: '';
335	  background: var(--c-yellow);
336	  border-radius: 50%;
337	  animation: hint-pulse 1.6s var(--ease-out) infinite;
338	}
339	
340	@keyframes hint-in {
341	  from {
342	    opacity: 0;
343	  }
344	}
345	
346	@keyframes hint-pulse {
347	  from {
348	    opacity: 0.6;
349	    transform: scale(1);
350	  }
351	
352	  to {
353	    opacity: 0;
354	    transform: scale(2.6);
355	  }
356	}
357	
358	/* Contained (portrait) hero: the right of lamp 2 is outside the view, so
359	   the hint sits under lamp 2's diffuser instead. */
360	@media (max-aspect-ratio: 5/4) {
361	  .hero__hint {
362	    top: 76%;
363	    left: 60%;
364	    transform: translateX(-50%);
365	  }
366	}
367	
368	/* Easter egg: all three lamps on -> "w nowym świetle" glows warm. A copy of
369	   the words fades in on top; its text is hidden from assistive tech
370	   (`/ ""`), so the heading is never read twice. */
371	.hero__glow {
372	  position: relative;
373	  display: inline-block;
374	}
375	
376	.hero__glow::after {
377	  position: absolute;
378	  inset: 0;
379	  color: var(--c-light-text);
380	  text-shadow:
381	    0 0 18px rgb(255 190 90 / 95%),
382	    0 0 42px rgb(255 160 60 / 70%);
383	  pointer-events: none;
384	  content: attr(data-text) / '';
385	  opacity: 0;
386	  transition: opacity var(--dur-zoom) var(--ease);
387	}
388	
389	.hero--lit-3 .hero__glow::after {
390	  opacity: 1;
391	}
392	
393	/* Reduced motion: no flicker and no pulse; switching is a plain fade */
394	@media (prefers-reduced-motion: reduce) {
395	  .light--on .light__glow {
396	    animation: none;
397	  }
398	
399	  .light__glow {
400	    transition-duration: var(--dur-fade);
401	  }
402	
403	  .hero__hint-dot::after {
404	    animation: none;
405	    opacity: 0;
406	  }
407	}
408

