2	
3	   Desktop (>= 1024): two mirrored rows, 648 | 936 and 936 | 648 at 1600.
4	   One 3-column grid does both: 648fr 272fr 648fr with 16 px gaps gives
5	   648 / 16 + 272 + 16 ... = 936 exactly at 1600 and scales proportionally.
6	   Row height scales with the column (518 at 1600, min 360), so both tiles
7	   keep their image's ratio and cover only crops once the 360 px floor applies.
8	
9	   Below 1024: one column, fixed height, image cropped with object-fit:
10	   cover (the srcset `sizes` in index.html account for that crop). */
11	.tiles {
12	  display: grid;
13	  grid-template-columns: minmax(0, 1fr);
14	  gap: 16px;
15	}
16	
17	.tile {
18	  --tile-fg: var(--c-black);
19	  --tile-pad: clamp(24px, 2.5vw + 8px, 48px);
20	
21	  position: relative;
22	  display: flex;
23	  flex-direction: column;
24	  justify-content: flex-end;
25	  height: clamp(440px, 60vw, 520px);
26	  overflow: hidden;
27	  color: var(--tile-fg);
28	  background: var(--tile-bg, var(--c-tile-stone));
29	  border-radius: 24px;
30	  isolation: isolate;
31	}
32	
33	.tile--thoro {
34	  --tile-fg: var(--c-white);
35	  --scrim: 52%;
36	  --tile-pos: 40% center;
37	}
38	
39	.tile--configurator {
40	  --tile-fg: var(--c-white);
41	  --scrim: 32%;
42	  --tile-bg: var(--c-tile-blue);
43	  --tile-pos: 85% center;
44	}
45	
46	.tile--catalog {
47	  --tile-bg: var(--c-tile-cream);
48	  --tile-pos: 85% center;
49	}
50	
51	.tile--smart {
52	  --tile-bg: var(--c-tile-stone);
53	  --tile-pos: 75% center;
54	}
55	
56	/* Image zoom on hover (comments spec 05): 1 -> 1.1, 500 ms ease-out, clipped
57	   by the tile's overflow. `scale` is neutralised under reduced motion. */
58	.tile__img {
59	  position: absolute;
60	  inset: 0;
61	  z-index: -1;
62	  width: 100%;
63	  height: 100%;
64	  object-fit: cover;
65	  object-position: var(--tile-pos, center);
66	  /* explicit 1, not the default none: under reduced motion the hover value
67	     is also 1, so nothing changes and no scale transition starts */
68	  scale: 1;
69	  transition: scale var(--dur-tile) var(--ease-out);
70	}
71	
72	.tile__body {
73	  display: flex;
74	  flex-direction: column;
75	  gap: 24px;
76	  align-items: flex-start;
77	  padding: var(--body-pad-top, var(--tile-pad)) var(--tile-pad) var(--tile-pad);
78	}
79	
80	/* Contrast scrim (design/NOTES.md): white text on THORO's photo and on
81	   Konfigurator's blue is under WCAG minimums, so a dark gradient sits behind
82	   the text block only. The body grows upward by --scrim-fade; the gradient
83	   is clear at its top edge and reaches full strength (--scrim) 8 px above
84	   the eyebrow, staying there to the bottom. Strengths are the measured
85	   minimum for 4.5:1 on the eyebrow and 3:1 on the title at every width
86	   (see NOTES.md). The body is not positioned, so the link's ::after still
87	   covers the whole tile. */
88	.tile--scrim {
89	  --scrim-fade: 48px;
90	  --body-pad-top: calc(var(--tile-pad) + var(--scrim-fade));
91	}
92	
93	.tile--scrim .tile__body {
94	  background: linear-gradient(
95	    to top,
96	    rgb(16 16 17 / var(--scrim)) calc(100% - var(--body-pad-top) + 8px),
97	    rgb(16 16 17 / 0%)
98	  );
99	}
100	
101	.tile__copy {
102	  display: flex;
103	  flex-direction: column;
104	  gap: 12px;
105	  font-weight: var(--fw-bold);
106	  line-height: 1.1;
107	}
108	
109	.tile__eyebrow {
110	  font-size: var(--fs-lead);
111	}
112	
113	.tile__title {
114	  font-size: var(--fs-tile-title);
115	  font-weight: inherit;
116	  line-height: inherit;
117	}
118	
119	/* Figma's forced line break (Konfigurator) only at desktop; narrower tiles wrap naturally */
120	.tile__title br {
121	  display: none;
122	}
123	
124	/* One focus target: the link wraps the pill, and its ::after covers the
125	   whole tile (the link itself stays unpositioned). */
126	.tile__link {
127	  display: inline-flex;
128	  border-radius: var(--radius-pill);
129	}
130	
131	.tile__link::after {
132	  position: absolute;
133	  inset: 0;
134	  content: '';
135	}
136	
137	/* Hover anywhere on the tile: zoom + button overlay (grey). Keyboard focus
138	   gets the same state. */
139	@media (hover: hover) {
140	  .tile:hover .tile__img {
141	    scale: var(--scale-tile-hover);
142	  }
143	
144	  .tile:hover .button::before {
145	    opacity: 1;
146	  }
147	}
148	
149	.tile:has(.tile__link:focus-visible) .tile__img {
150	  scale: var(--scale-tile-hover);
151	}
152	
153	.tile__link:focus-visible .button::before {
154	  opacity: 1;
155	}
156	
157	/* Below 1024, tiles with a flat background (configurator, catalog, smart)
158	   stack: image block on top, text underneath on the same colour (the images'
159	   own background, so the join is invisible). Overlaying the text, as on
160	   desktop, would put it across the device mockups at these widths. THORO is
161	   a photo with a dark lower half and keeps the overlay. The `sizes` in
162	   index.html follow these boxes: wide images cover a 4:3 box at 1.355x the
163	   tile width, a 16:9 box at ~1.017x. */
164	@media (width < 1024px) {
165	  .tile--split {
166	    justify-content: flex-start;
167	    height: auto;
168	  }
169	
170	  .tile--split .tile__img {
171	    position: static;
172	    z-index: auto;
173	    height: auto;
174	    aspect-ratio: 4 / 3;
175	  }
176	
177	  /* 32 px clears the hover zoom's overhang (5 % of the image box) and,
178	     on Konfigurator, holds the scrim's fade on the flat colour */
179	  .tile--split .tile__body {
180	    --body-pad-top: 32px;
181	  }
182	}
183	
184	@media (640px <= width < 1024px) {
185	  .tile--split .tile__img {
186	    aspect-ratio: 16 / 9;
187	  }
188	}
189	
190	@media (width >= 1024px) {
191	  .tiles {
192	    grid-template-columns: 648fr 272fr 648fr;
193	  }
194	
195	  .tile__title br {
196	    display: inline;
197	  }
198	
199	  /* Row height from the column width (not aspect-ratio + min-height, which
200	     would force a min width and overflow the grid at 1024): narrow tile width
201	     (column - 32) * 0.4133, times 518/648 = 0.3304. 518 px at 1600. */
202	  .tile {
203	    height: max(360px, (min(100vw - 32px, 1600px) - 32px) * 0.3304);
204	  }
205	
206	  /* row 1: narrow | wide; row 2: wide | narrow */
207	  .tile--row1.tile--wide {
208	    grid-column: 2 / 4;
209	  }
210	
211	  .tile--row2.tile--wide {
212	    grid-column: 1 / 3;
213	  }
214	
215	  .tile--row2.tile--narrow {
216	    grid-column: 3;
217	  }
218	}
219

1	/* VP's section (Figma 1:593, design/figma/04-design-context-vps.tsx; PLAN.md §3.5).
2	   `.vps` is the section wrapper shared with the tiles (css/tiles.css):
3	   86 px vertical padding, 16 px gutter, 1600 max, 64 px between benefits and tiles. */
4	.vps {
5	  display: flex;
6	  flex-direction: column;
7	  gap: clamp(40px, 4vw, 64px);
8	  width: min(100% - 2 * var(--gutter), var(--container));
9	  margin-inline: auto;
10	  padding-block: clamp(48px, 4.5vw, 86px);
11	}
12	
13	/* Benefits: 5 at desktop (32 px gaps), 3 + 2 at tablet, 2 columns on phones
14	   (design/NOTES.md). */
15	.benefits {
16	  display: grid;
17	  grid-template-columns: repeat(2, minmax(0, 1fr));
18	  gap: 8px;
19	}
20	
21	.benefit {
22	  display: flex;
23	  flex-direction: column;
24	  gap: 24px;
25	  padding: 16px;
26	}
27	
28	.benefit__icon {
29	  flex: none;
30	  color: var(--c-black);
31	}
32	
33	.benefit__copy {
34	  display: flex;
35	  flex-direction: column;
36	  gap: 8px;
37	}
38	
39	.benefit__title {
40	  font-size: var(--fs-lead);
41	  font-weight: var(--fw-bold);
42	  line-height: 1.1;
43	  color: var(--c-black);
44	}
45	
46	.benefit__text {
47	  font-size: var(--fs-14);
48	  font-weight: var(--fw-medium);
49	  line-height: 1.2;
50	  color: var(--c-ink);
51	}
52	
53	@media (width >= 640px) {
54	  .benefits {
55	    grid-template-columns: repeat(3, minmax(0, 1fr));
56	    gap: 16px;
57	  }
58	}
59	
60	@media (width >= 1024px) {
61	  .benefits {
62	    grid-template-columns: repeat(5, minmax(0, 1fr));
63	    gap: 32px;
64	  }
65	}
66

1	/* Shader section (PLAN.md §3.7; design/frames/screen.png, 1920 x 835).
2	   Values are measured from the PNG (1:707 is image-only in Figma):
3	   heading Bold 52/1.1, letter-spacing -1 %, #f0f0f3; button Bold 18/24 with
4	   16/26 padding (131 x 56); subline Medium 17/1.2 in #e7e7e7. Gaps 36 / 20.
5	
6	   Progressive enhancement: the section's own background is the static
7	   fallback (no WebGL, no JS, lost context). js/shader.js fades the canvas in
8	   over it once the first WebGL frame is drawn (.shader--ready). */
9	.shader {
10	  position: relative;
11	  display: grid;
12	  place-items: center;
13	  min-height: clamp(480px, 43.5vw, 835px);
14	  padding: 70px var(--gutter) 64px; /* block centre 3 px below the middle, as in the frame */
15	  overflow: hidden;
16	  color: var(--c-shader-text);
17	  text-align: center;
18	  background:
19	    linear-gradient(to bottom, var(--c-black) 22%, rgb(16 16 17 / 0%) 96%),
20	    linear-gradient(
21	      40deg,
22	      var(--c-shader-gold) 0%,
23	      var(--c-yellow) 11%,
24	      var(--c-shader-olive) 24%,
25	      var(--c-shader-deep) 33%,
26	      var(--c-shader-mid) 47%,
27	      var(--c-shader-olive) 60%,
28	      var(--c-shader-mid) 71%,
29	      var(--c-shader-deep) 81%,
30	      var(--c-shader-mid) 92%
31	    ),
32	    var(--c-black);
33	}
34	
35	.shader__canvas {
36	  position: absolute;
37	  inset: 0;
38	  width: 100%;
39	  height: 100%;
40	  opacity: 0;
41	  transition: opacity var(--dur-fade) var(--ease);
42	}
43	
44	.shader--ready .shader__canvas {
45	  opacity: 1;
46	}
47	
48	/* Text and button are static, above the animation (comments spec 06) */
49	.shader__content {
50	  position: relative;
51	  display: flex;
52	  flex-direction: column;
53	  align-items: center;
54	}
55	
56	.shader__title {
57	  max-width: 13.5em;
58	  font-size: var(--fs-shader);
59	  font-weight: var(--fw-bold);
60	  line-height: 1.1;
61	  letter-spacing: -0.01em;
62	}
63	
64	.shader__cta {
65	  margin-top: 36px;
66	  padding-inline: 26px;
67	  font-size: var(--fs-18);
68	  line-height: 24px;
69	}
70	
71	.shader__note {
72	  max-width: 15em;
73	  margin-top: 20px;
74	  font-size: var(--fs-17);
75	  font-weight: var(--fw-medium);
76	  line-height: 1.2;
77	  color: var(--c-line);
78	}
