1	/* Footer (Figma 1:708, design/figma/05-design-context-footer.tsx; PLAN.md §3.8).
2	   Three bands on the 1600 column: top (logo + socials, 5 link columns),
3	   bottom (payments, awards, shops), caption (VAT line, badges, contact).
4	   Type: headings Bold 13/1.1, links Medium 13/1.1, caption Medium 12/1.1,
5	   all #1e1e1e. Layout below the design width: PLAN.md §3.8. */
6	.footer {
7	  color: var(--c-ink);
8	  background: var(--c-white);
9	}
10	
11	.footer__top,
12	.footer__bottom,
13	.footer__caption {
14	  width: min(100% - 2 * var(--gutter), var(--container));
15	  margin-inline: auto;
16	}
17	
18	.footer__heading {
19	  font-size: var(--fs-13);
20	  font-weight: var(--fw-bold);
21	  line-height: 1.1;
22	}
23	
24	/* Links carry 6 px vertical padding with a 2 px list gap: the same 28 px
25	   rhythm as Figma's 14 px gap, but a 26 px tall target instead of 14 px. */
26	.footer__link {
27	  display: inline-block;
28	  padding-block: 6px;
29	  font-size: var(--fs-13);
30	  font-weight: var(--fw-medium);
31	  line-height: 1.1;
32	}
33	
34	@media (hover: hover) {
35	  .footer__link:hover {
36	    text-decoration: underline;
37	    text-underline-offset: 3px;
38	  }
39	}
40	
41	/* Top band */
42	.footer__top {
43	  display: flex;
44	  flex-direction: column;
45	  gap: 40px;
46	  padding-block: 64px 40px;
47	}
48	
49	.footer__brand {
50	  display: flex;
51	  flex-direction: column;
52	  gap: 8px;
53	  align-items: center;
54	  align-self: flex-start;
55	}
56	
57	.footer__logo {
58	  display: grid;
59	  place-items: center;
60	  width: 160px;
61	  height: 44px;
62	}
63	
64	.footer__social {
65	  display: flex;
66	  gap: 2px;
67	}
68	
69	.footer__social-link {
70	  display: grid;
71	  place-items: center;
72	  width: 48px;
73	  height: 48px;
74	  color: var(--c-black);
75	  border-radius: var(--radius-pill);
76	}
77	
78	.footer__nav {
79	  display: grid;
80	  grid-template-columns: repeat(2, minmax(0, 1fr));
81	  gap: 32px 24px;
82	}
83	
84	.footer__column {
85	  display: flex;
86	  flex-direction: column;
87	  gap: 18px; /* + the first link's 6 px padding = Figma's 24 */
88	}
89	
90	.footer__links {
91	  display: flex;
92	  flex-direction: column;
93	  gap: 2px;
94	  align-items: flex-start;
95	  margin-bottom: -6px; /* the last link's padding is tap area, not layout */
96	}
97	
98	/* Bottom band: three groups, stacked below 1024 */
99	.footer__bottom {
100	  display: flex;
101	  flex-direction: column;
102	  padding-bottom: 16px;
103	  border-top: 1px solid var(--c-line);
104	}
105	
106	.footer__group {
107	  display: flex;
108	  flex-direction: column;
109	  gap: 24px;
110	  padding-block: 32px;
111	}
112	
113	.footer__group + .footer__group {
114	  border-top: 1px solid var(--c-line);
115	}
116	
117	/* 5 cells of 57 x 36 per row (43 x 24 logo + 7 / 6 padding), 8 px gaps */
118	.footer__payments {
119	  display: flex;
120	  flex-wrap: wrap;
121	  gap: 8px;
122	  max-width: 317px;
123	}
124	
125	.footer__payment {
126	  padding: 6px 7px;
127	}
128	
129	.footer__awards {
130	  display: flex;
131	  flex-wrap: wrap;
132	  gap: 3px;
133	  max-width: 294px;
134	}
135	
136	.footer__flags {
137	  display: flex;
138	  flex-wrap: wrap;
139	  gap: 8px;
140	}
141	
142	.footer__flag {
143	  display: grid;
144	  place-items: center;
145	  width: 32px;
146	  height: 32px;
147	  border-radius: var(--radius-pill);
148	}
149	
150	.footer__flag img {
151	  border-radius: 50%;
152	}
153	
154	/* Caption */
155	.footer__caption {
156	  display: flex;
157	  flex-direction: column;
158	  gap: 16px;
159	  padding-block: 32px;
160	  font-size: var(--fs-12);
161	  font-weight: var(--fw-medium);
162	  line-height: 1.1;
163	}
164	
165	.footer__vat {
166	  display: flex;
167	  flex-wrap: wrap;
168	  gap: 16px 32px;
169	  align-items: center;
170	}
171	
172	.footer__rule {
173	  display: none;
174	}
175	
176	.footer__badges {
177	  display: flex;
178	  gap: 8px;
179	}
180	
181	.footer__contact {
182	  display: flex;
183	  flex-wrap: wrap;
184	  gap: 4px 24px;
185	  align-items: center;
186	}
187	
188	/* tap area kept, line height as in Figma */
189	.footer__contact .footer__link {
190	  margin-block: -6px;
191	  font-size: inherit;
192	}
193	
194	.footer__phone {
195	  display: flex;
196	  gap: 16px;
197	  align-items: center;
198	}
199	
200	@media (width >= 640px) {
201	  .footer__nav {
202	    grid-template-columns: repeat(3, minmax(0, 1fr));
203	  }
204	}
205	
206	@media (width >= 1024px) {
207	  .footer__nav {
208	    grid-template-columns: repeat(5, minmax(0, 1fr));
209	  }
210	
211	  /* three equal columns (512 at 1600) including their padding, as in Figma */
212	  .footer__bottom {
213	    display: grid;
214	    grid-template-columns: repeat(3, minmax(0, 1fr));
215	    gap: 32px;
216	  }
217	
218	  .footer__group {
219	    padding: 32px;
220	    border-right: 1px solid var(--c-line);
221	  }
222	
223	  .footer__group:first-child {
224	    padding-left: 0;
225	  }
226	
227	  .footer__group:last-child {
228	    border-right: 0;
229	  }
230	
231	  .footer__group + .footer__group {
232	    border-top: 0;
233	  }
234	
235	  .footer__caption {
236	    gap: 8px;
237	  }
238	
239	  .footer__vat {
240	    flex-wrap: nowrap;
241	  }
242	
243	  .footer__vat p {
244	    flex: none;
245	  }
246	
247	  .footer__rule {
248	    display: block;
249	    flex: 1 1 auto;
250	    height: 1px;
251	    background: var(--c-line);
252	  }
253	}
254	
255	/* From 1280: one row as in the design. The column gap scales so the row fits
256	   at 1280 and is exactly Figma's 96 at 1920. */
257	@media (width >= 1280px) {
258	  .footer__top {
259	    flex-direction: row;
260	    justify-content: space-between;
261	    padding-block: 96px 64px;
262	  }
263	
264	  .footer__nav {
265	    display: flex;
266	    gap: clamp(40px, 5vw, 96px);
267	  }
268	
269	  .footer__link {
270	    white-space: nowrap;
271	  }
272	}
