1	// Shared helpers for the spec files.
2	
3	/** Load the page. The first-visit lamp hint is marked as seen unless asked. */
4	export async function openPage(page, { showHint = false } = {}) {
5	  if (!showHint) {
6	    await page.addInitScript(() => {
7	      try {
8	        window.localStorage.setItem('sollux:lamp-hint-seen', '1');
9	      } catch {
10	        // storage blocked: the hint just shows
11	      }
12	    });
13	  }
14	  await page.goto('index.html');
15	}
16	
17	/** A computed style value, optionally of a pseudo-element. */
18	export function styleOf(locator, property, pseudo = null) {
19	  return locator.evaluate(
20	    (el, [prop, pseudoEl]) => getComputedStyle(el, pseudoEl)[prop],
21	    [property, pseudo],
22	  );
23	}
24	
25	/** Bounding box in CSS px (rounded to 0.01). */
26	export async function box(locator) {
27	  const b = await locator.boundingBox();
28	  const r = (n) => Math.round(n * 100) / 100;
29	  return { x: r(b.x), y: r(b.y), width: r(b.width), height: r(b.height) };
30	}
31	
32	/** Index of the active hero slide. */
33	export function activeSlide(page) {
34	  return page.evaluate(() =>
35	    [...document.querySelectorAll('[data-slide]')].findIndex((s) =>
36	      s.classList.contains('hero__slide--active'),
37	    ),
38	  );
39	}
40	
41	/** The x scale of a progress segment's fill (1 = full). */
42	export function fillScale(page, index) {
43	  return page.evaluate((i) => {
44	    const fill = document.querySelectorAll('[data-slider-dot]')[i].firstElementChild;
45	    const transform = getComputedStyle(fill).transform;
46	    return transform === 'none' ? 1 : new DOMMatrixReadOnly(transform).a;
47	  }, index);
48	}
