1	// PLAN.md §4, criterion 5 and the lamp light: toggling, alignment with the
2	// stage, the room dim, the first-visit hint and the headline easter egg.
3	import { readFileSync } from 'node:fs';
4	import { test, expect } from '@playwright/test';
5	import { openPage, styleOf, box } from './helpers.js';
6	
7	const POSITIONS = JSON.parse(
8	  readFileSync(new URL('../design/lamp-positions.json', import.meta.url), 'utf8'),
9	).lamps.map((l) => l.percent);
10	
11	// Lamp box vs. its reference position in the stage, in CSS px (proposed;
12	// sub-pixel rounding only, PLAN.md §4).
13	const ALIGN_TOLERANCE = 1;
14	
15	const DIM = { 1: 0.06, 2: 0.11, 3: 0.15 }; // --lamp-dim-1/2/3 in tokens.css
16	
17	const lamp = (page, n) => page.locator(`.lamp--${n}`);
18	const glow = (page, n) => page.locator(`.light--${n} .light__glow`);
19	
20	test.describe('switching a lamp', () => {
21	  test.beforeEach(async ({ page }) => {
22	    await openPage(page);
23	    await page.locator('[data-slider-pause]').click();
24	  });
25	
26	  for (const slide of [1, 2]) {
27	    test(`toggles aria-pressed and the glow on slide ${slide}`, async ({ page }) => {
28	      if (slide === 2) await page.locator('[data-slider-dot]').nth(1).click();
29	
30	      for (const n of [1, 2, 3]) {
31	        await expect(lamp(page, n)).toHaveAttribute('aria-pressed', 'false');
32	        expect(await styleOf(glow(page, n), 'opacity')).toBe('0');
33	
34	        await lamp(page, n).click();
35	        await expect(lamp(page, n)).toHaveAttribute('aria-pressed', 'true');
36	        await expect.poll(() => styleOf(glow(page, n), 'opacity')).toBe('1');
37	
38	        await lamp(page, n).click();
39	        await expect(lamp(page, n)).toHaveAttribute('aria-pressed', 'false');
40	        await expect.poll(() => styleOf(glow(page, n), 'opacity')).toBe('0');
41	      }
42	    });
43	  }
44	
45	  test('works with the keyboard (Enter and Space)', async ({ page }) => {
46	    await lamp(page, 1).focus();
47	    await page.keyboard.press('Enter');
48	    await expect(lamp(page, 1)).toHaveAttribute('aria-pressed', 'true');
49	    await page.keyboard.press('Space');
50	    await expect(lamp(page, 1)).toHaveAttribute('aria-pressed', 'false');
51	  });
52	
53	  test('the room dims a little more with each lamp, and not at all with none', async ({ page }) => {
54	    const dim = page.locator('.hero__dim');
55	    expect(await styleOf(dim, 'opacity')).toBe('0');
56	    for (const n of [1, 2, 3]) {
57	      await lamp(page, n).click();
58	      await expect.poll(async () => Number(await styleOf(dim, 'opacity'))).toBeCloseTo(DIM[n], 3);
