3	// The viewport is taller than the hero (max 1080 px), so the cursor can leave
4	// the hero downwards without leaving the page.
5	import { test, expect } from '@playwright/test';
6	import { openPage, box } from './helpers.js';
7	
8	const MAX_PX = 12; // --lamp-parallax at a 1920 px stage
9	const DEPTH = { 1: 0.55, 2: 0.8, 3: 1 }; // data-depth
10	const POOL = 0.3; // --lamp-parallax-pool
