14	async function positions(page) {
15	  const of = async (selector) => {
16	    const list = [];
17	    for (const n of [1, 2, 3]) list.push(await box(page.locator(selector(n))));
18	    return list;
19	  };
20	  return {
21	    lamps: await of((n) => `.lamp--${n}`),
22	    peeks: await of((n) => `.light--${n} .light__peek`),
23	    pools: await of((n) => `.light--${n} .light__pool`),
24	  };
25	}
26	
27	const inlineParallax = (page) =>
28	  page.evaluate(() =>
29	    [...document.querySelectorAll('[data-lamp], [data-light]')].some((el) =>
30	      (el.getAttribute('style') || '').includes('--parallax'),
31	    ),
32	  );
33	
34	test('lamps follow the cursor by depth, and the light with them', async ({ page }) => {
35	  await openPage(page);
36	  const rest = await positions(page);
37	
38	  // left edge, vertical middle of the 1080 px hero: direction (-1, 0)
39	  await page.mouse.move(960, 540);
40	  await page.mouse.move(0, 540, { steps: 10 });
41	  await page.waitForTimeout(1500); // the follow settles in well under a second
42	  const moved = await positions(page);
43	
44	  for (const n of [1, 2, 3]) {
45	    const i = n - 1;
46	    const dx = moved.lamps[i].x - rest.lamps[i].x;
47	    expect(dx).toBeCloseTo(-MAX_PX * DEPTH[n], 1);
48	    expect(moved.lamps[i].y - rest.lamps[i].y).toBeCloseTo(0, 1);
49	    // the diffuser glow moves with its lamp, the pool on the rock less
50	    expect(moved.peeks[i].x - rest.peeks[i].x).toBeCloseTo(dx, 1);
51	    expect(moved.pools[i].x - rest.pools[i].x).toBeCloseTo(dx * POOL, 1);
52	  }
53	});
