63	  await page.mouse.move(960, 1150, { steps: 10 }); // below the hero
64	  await page.waitForTimeout(100);
65	  const midway = await box(page.locator('.lamp--3'));
66	  expect(midway.x).not.toBeCloseTo(rest.lamps[2].x, 1); // eases, no jump
