1	// PLAN.md §4, criterion 6: the WebGL shader draws, animates, and falls back to
2	// the static CSS gradient without WebGL.
3	import { test, expect } from '@playwright/test';
4	import sharp from 'sharp';
5	import { openPage, styleOf } from './helpers.js';
6	
7	/** Screenshot of the canvas alone: section background and text hidden. */
8	async function canvasShot(page) {
9	  await page.addStyleTag({
10	    content: '.shader { background: #000 !important; } .shader__content { visibility: hidden; }',
11	  });
12	  return page.locator('[data-shader-canvas]').screenshot({ animations: 'allow' });
13	}
14	
15	async function stats(png) {
16	  const { channels } = await sharp(png).stats();
17	  return {
18	    mean: (channels[0].mean + channels[1].mean + channels[2].mean) / 3,
19	    stdev: (channels[0].stdev + channels[1].stdev + channels[2].stdev) / 3,
20	  };
21	}
22	
23	test('the canvas has a WebGL context and draws non-blank, moving pixels', async ({ page }) => {
24	  await openPage(page);
25	  const section = page.locator('[data-shader]');
26	  await section.scrollIntoViewIfNeeded();
27	  await expect(section).toHaveClass(/shader--ready/);
28	
29	  const hasContext = await page
30	    .locator('[data-shader-canvas]')
31	    .evaluate((c) => c.getContext('webgl') !== null);
32	  expect(hasContext).toBe(true);
33	
34	  const first = await canvasShot(page);
35	  const s = await stats(first);
36	  expect(s.mean).toBeGreaterThan(10); // not black
37	  expect(s.stdev).toBeGreaterThan(5); // not a flat colour
38	
39	  await page.waitForTimeout(1000);
40	  const second = await page.locator('[data-shader-canvas]').screenshot({ animations: 'allow' });
41	  expect(first.equals(second)).toBe(false); // animating
42	});
43	
44	test('without WebGL the static gradient shows, with no errors', async ({ page }) => {
45	  const errors = [];
46	  page.on('pageerror', (e) => errors.push(e.message));
47	  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
48	  await page.addInitScript(() => {
49	    const original = HTMLCanvasElement.prototype.getContext;
50	    HTMLCanvasElement.prototype.getContext = function (type, ...rest) {
51	      if (/webgl/.test(type)) return null;
52	      return original.call(this, type, ...rest);
53	    };
54	  });
55	  await openPage(page);
56	  const section = page.locator('[data-shader]');
57	  await section.scrollIntoViewIfNeeded();
58	  await page.waitForTimeout(500);
59	
60	  await expect(section).not.toHaveClass(/shader--ready/);
61	  expect(await styleOf(page.locator('[data-shader-canvas]'), 'opacity')).toBe('0');
62	  expect(await styleOf(section, 'backgroundImage')).toMatch(/gradient/);
63	  expect(errors).toEqual([]);
64	});
65

